export const supplementalOperationsEntries: JournalEntry[] = [
  {
    id: 'skill-evaluation-protocol', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'comparer-un-skill-avec-un-protocole', title: 'Un skill améliore-t-il l’agent ? Construire une comparaison contrôlée',
        description: 'Évaluez un skill avec des tâches appariées, des critères de résultat, des traces et des vérifications de régression.', category: 'Exploitation & R&D',
        introduction: 'Un skill bien écrit peut encore être inutile, déclenché au mauvais moment ou perturber une tâche qu’il devait aider. Pour savoir s’il améliore réellement le comportement, il faut comparer des exécutions équivalentes avec et sans le skill et regarder plus que la réponse finale. L’évaluation porte sur la tâche, l’agent, ses outils et l’environnement dans lequel il agit. Les guides d’OpenAI et d’Anthropic recommandent de rendre explicites les critères de succès, d’enregistrer les traces et de répéter les essais. Ils ne promettent pas qu’un protocole unique convient à tous les produits. La méthode ci-dessous est une proposition reproductible, à adapter au risque et au coût du cas étudié.',
        sources: [oaSkillEval, anthEvals, oaEvals, skillSpec],
        sections: [
          { title: 'Commencer par une affirmation réfutable', sourceUrls: [oaSkillEval.url, anthEvals.url], paragraphs: [
            'Écrivez une hypothèse qui peut échouer : « sur les demandes de mise en forme de rapports, cette procédure fait produire le tableau requis plus régulièrement sans augmenter les erreurs de données ». Évitez une formulation comme « le skill rend l’agent meilleur », qui ne précise ni tâche ni résultat. Délimitez les entrées concernées, les utilisateurs, les outils disponibles et la version de l’agent. Définissez aussi ce qui compte comme un échec critique : sortie manquante, opération non autorisée, information inventée ou format inexploitable. Cette définition transforme une impression après démonstration en question que des cas d’essai peuvent trancher.',
            'Les évaluations d’agents se distinguent d’un simple test de texte parce qu’un agent peut appeler des outils, modifier un état et s’adapter à plusieurs tours. Les guides officiels décrivent donc les tâches, les traces, le résultat final et le dispositif qui exécute et note les essais. Leurs explications viennent de fournisseurs et constituent des pratiques à considérer, pas une preuve indépendante que tel format de grader est suffisant. Pour un skill, gardez le même principe : annoncer la mesure avant de regarder les résultats évite de déplacer les critères pour faire paraître le changement positif.'
          ] },
          { title: 'Construire des paires de cas comparables', paragraphs: [
            'Choisissez des demandes réalistes couvrant le cas courant, les variantes et les limites du skill. Chaque cas doit avoir une entrée stable, les prérequis requis et une définition du résultat attendu. Une première version peut contenir une quinzaine de cas courts, mais le nombre n’est pas une garantie statistique ; il dépend de la diversité des situations et de la variabilité du système. Pour chaque cas, lancez la version de référence sans skill et la version candidate avec skill. Gardez les mêmes modèle, paramètres, outils, permissions, documents et état initial quand c’est possible, et consignez chaque différence.',
            'L’ordre peut influencer un système qui conserve un contexte ou un état entre essais. Exécutez donc chaque variante dans une session indépendante, randomisez l’ordre des paires si l’outillage le permet et évitez de réutiliser des traces comme entrées involontaires. Si le résultat est probabiliste, répétez certains cas et présentez la distribution ou les désaccords, pas seulement le meilleur run. Les essais répétés coûtent davantage ; concentrez-les sur les cas qui changent la décision ou où l’échec est important. Une petite suite bien décrite est plus utile qu’une grande collection de prompts sans référence attendue.'
          ] },
          { title: 'Noter résultat, processus et facture opérationnelle', sourceUrls: [oaSkillEval.url, oaEvals.url, anthEvals.url], paragraphs: [
            'Séparez les dimensions. Le résultat métier vérifie que l’artefact attendu existe et satisfait les critères. Le processus regarde si le skill a été activé au moment opportun, si les étapes requises ont été suivies et si l’agent a évité les appels d’outils superflus. La qualité de réponse apprécie lisibilité et complétude. Enfin, mesurez le temps, les appels d’outils ou le coût quand cette donnée est disponible. Un skill peut améliorer un score de format tout en augmentant fortement les étapes ou en entraînant une activation trop fréquente ; un score global pondéré cacherait ce compromis.',
            'Privilégiez des contrôles déterministes pour les propriétés mécaniques : présence d’un fichier, validité d’un schéma, nombre de champs, résultat d’une requête ou absence d’un motif interdit. Un évaluateur humain peut examiner la pertinence, l’ambiguïté ou la sécurité. Un grader fondé sur un modèle peut aider à trier un volume plus important, mais vérifiez son accord avec des annotations humaines et examinez les faux positifs. Les docs OpenAI parlent de trace et de contrôles pour les skills ; Anthropic distingue trace et état final. Ce sont des repères utiles, mais le protocole doit dire précisément qui note chaque dimension et comment les désaccords sont résolus.'
          ] },
          { title: 'Exemple fictif : décider si une procédure de rapport mérite d’être conservée', paragraphs: [
            'Exemple fictif : une équipe prépare des synthèses mensuelles à partir d’un CSV et d’une consigne. Le skill décrit les colonnes, signale les valeurs manquantes et produit un tableau de contrôle. Préparez dix fichiers synthétiques, dont deux avec des dates incohérentes et un avec une colonne absente. Pour chaque fichier, le résultat attendu est une synthèse et un avertissement exact, sans inventer de valeur. Comparez une exécution avec le skill à une exécution sans, dans des sessions neuves. Un script vérifie les colonnes et avertissements ; une personne relit les formulations et les décisions d’abstention.',
            'Supposons que la version candidate réussisse davantage les vérifications de schéma, mais oublie les avertissements dans un cas limite et ajoute plusieurs appels d’outils. La décision raisonnable n’est pas de proclamer une amélioration générale : corrigez le cas limite, répétez la paire concernée, puis évaluez si le surcoût est acceptable. Si le skill ne s’active presque jamais sur les cas visés, il faut revoir son nom, sa description ou sa portée avant d’en juger les instructions. Ces résultats sont hypothétiques ; ils illustrent le protocole et ne correspondent à aucune expérience réellement menée ni à un effet mesuré.'
          ] },
          { title: 'Accepter, corriger ou retirer avec des règles connues', paragraphs: [
            'Fixez avant le test des critères d’acceptation séparés : par exemple aucune dégradation sur les erreurs critiques, réussite des contrôles requis et coût supplémentaire sous un plafond choisi localement. Précisez les cas qui bloquent une adoption même si la moyenne est favorable. Conservez un jeu de régression qui inclut les nouveaux échecs et quelques entrées ordinaires. À chaque modification importante du modèle, de l’outil ou du skill, rejouez le périmètre concerné ; une évaluation ancienne ne certifie pas une version différente. Archivez la version, les paramètres, les cas, les sorties et les décisions pour qu’une autre personne puisse refaire l’analyse.',
            'Une conclusion doit rester bornée : « le skill a amélioré ces contrôles sur ces cas avec cette configuration » est défendable ; « ce skill améliore les agents » ne l’est pas. Cette méthode coûte du temps et ne couvre pas les situations absentes du corpus. Elle est particulièrement utile pour une procédure réutilisée, une action qui modifie des données ou une défaillance coûteuse. Pour une note ponctuelle sans effet externe, une revue manuelle légère peut suffire. Le takeaway pratique est simple : évaluez le besoin qui a motivé le skill, et gardez la trace des cas où il ne fait pas mieux.'
          ] }
        ],
        takeaway: 'Écrivez une hypothèse avant le changement, comparez des cas appariés, notez résultat et trace, puis gardez les échecs comme tests de régression. Une conclusion ne vaut que pour les tâches et versions évaluées.',
        service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'evaluate-a-skill-with-a-controlled-protocol', title: 'Does a skill improve an agent? Build a controlled comparison',
        description: 'Evaluate a skill with paired tasks, outcome criteria, traces, and regression checks.', category: 'Operations & R&D',
        introduction: 'A carefully written skill can still be useless, trigger at the wrong time, or disrupt the task it was meant to help. To find out whether it improves behavior, compare equivalent runs with and without the skill and inspect more than the final answer. The evaluation concerns the task, agent, tools, and environment in which it acts. OpenAI and Anthropic guides recommend making success criteria explicit, recording traces, and repeating trials. They do not claim that one protocol fits every product. The method below is a reproducible proposal to adapt to the risk and cost of the use case.',
        sources: [oaSkillEval, anthEvals, oaEvals, skillSpec],
        sections: [
          { title: 'Start with a falsifiable claim', sourceUrls: [oaSkillEval.url, anthEvals.url], paragraphs: [
            'Write a hypothesis that could fail: “for report-formatting requests, this procedure makes the required table more consistent without increasing data errors.” Avoid “the skill makes the agent better,” which specifies neither task nor outcome. Bound the relevant inputs, users, available tools, and agent version. Define critical failures too: a missing output, an unauthorized operation, invented information, or an unusable format. This turns an impression after a demo into a question that test cases can answer.',
            'Agent evaluations differ from plain text tests because an agent can call tools, change state, and adapt over multiple turns. Official guides therefore describe tasks, traces, final outcomes, and the harness that runs and scores trials. Those explanations come from vendors and are practices to consider, not independent proof that a particular grader is sufficient. For a skill, keep the same principle: state the measure before inspecting results so the criteria do not move to make the change look positive.'
          ] },
          { title: 'Build comparable pairs of cases', paragraphs: [
            'Choose realistic requests covering the common case, variations, and the skill’s limits. Each case needs a stable input, required prerequisites, and a definition of the expected result. An initial suite might contain fifteen short cases, but that number is no statistical guarantee; it depends on scenario diversity and system variability. For each case, run the baseline without the skill and the candidate with it. Keep the model, parameters, tools, permissions, documents, and starting state the same when possible, and record every difference.',
            'Order can affect a system that retains context or state between trials. Run each variant in an independent session, randomize pair order if the harness permits, and avoid reusing traces as accidental inputs. If output is probabilistic, repeat selected cases and report the spread or disagreements, not just the best run. Repeated trials cost more, so focus them on cases that change the decision or where failure matters. A small, well-described suite is more useful than a large prompt collection with no expected reference.'
          ] },
          { title: 'Score outcomes, process, and operating cost', sourceUrls: [oaSkillEval.url, oaEvals.url, anthEvals.url], paragraphs: [
            'Separate the dimensions. The business outcome checks whether the expected artifact exists and meets criteria. Process checks whether the skill activated when appropriate, whether required steps were followed, and whether the agent avoided unnecessary tool calls. Response quality covers clarity and completeness. Finally, measure time, tool calls, or cost where available. A skill can improve a formatting score while greatly increasing the number of steps or triggering too often; one weighted score would conceal that trade-off.',
            'Prefer deterministic checks for mechanical properties: file presence, schema validity, field counts, query results, or absence of a forbidden pattern. A human can review relevance, ambiguity, and safety. A model grader may help triage larger volumes, but check its agreement with human annotations and inspect false positives. OpenAI’s skill material discusses traces and checks; Anthropic distinguishes traces from final state. These are useful reference points, but the protocol must say who scores each dimension and how disagreements are resolved.'
          ] },
          { title: 'Hypothetical example: decide whether to keep a reporting procedure', paragraphs: [
            'Hypothetical example: a team prepares monthly summaries from a CSV and a request. The skill describes the columns, flags missing values, and produces a validation table. Prepare ten synthetic files, including two with inconsistent dates and one missing a column. The expected result for each is a summary and an accurate warning, with no invented values. Compare one run with the skill against one without it in fresh sessions. A script checks columns and warnings; a person reviews phrasing and abstention decisions.',
            'Suppose the candidate passes more schema checks but misses a warning in one edge case and adds several tool calls. The reasonable response is not to proclaim a general improvement: fix the edge case, repeat the affected pair, then decide whether the overhead is acceptable. If the skill rarely activates on its intended cases, review its name, description, or scope before judging the instructions. These results are hypothetical; they illustrate a protocol and are not an experiment that was actually run or an effect that was measured.'
          ] },
          { title: 'Accept, revise, or retire under known rules', paragraphs: [
            'Set acceptance criteria before testing, separately: for example, no degradation on critical errors, passing the required checks, and extra cost below a locally chosen ceiling. Specify cases that block adoption even if the average looks favorable. Keep a regression set with new failures and ordinary inputs. After a meaningful model, tool, or skill change, rerun the relevant scope; an old evaluation does not certify a different version. Archive the version, settings, cases, outputs, and decisions so another person can reproduce the analysis.',
            'Keep the conclusion bounded: “the skill improved these checks on these cases with this configuration” is defensible; “this skill improves agents” is not. The method takes time and cannot cover situations missing from the suite. It is especially useful for a repeated procedure, an action that changes data, or a costly failure. For a one-off note with no external effect, a light manual review may be enough. The practical takeaway is to evaluate the need that motivated the skill and preserve cases where it does not help.'
          ] }
        ],
        takeaway: 'State a hypothesis before changing anything, compare paired cases, score outcomes and traces, and keep failures as regression tests. A conclusion applies only to the tasks and versions that were evaluated.',
        service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'skill-library-curation', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'curer-bibliotheque-skills-et-savoir-retirer', title: 'Pourquoi une bibliothèque de skills doit aussi savoir supprimer',
        description: 'Évitez les consignes redondantes et conflictuelles grâce à un inventaire, une évaluation et un cycle de retrait réversible.', category: 'Exploitation & R&D',
        introduction: 'Ajouter une instruction réutilisable est facile ; l’enlever demande souvent davantage de confiance. Les bibliothèques de skills s’encombrent de doublons, de procédures obsolètes, de descriptions qui se chevauchent et de consignes rarement activées. La documentation d’OpenAI présente les skills comme des paquets de procédures et de ressources, tandis que le standard Agent Skills décrit une structure partagée. OpenAI recommande aussi d’évaluer si le skill a été déclenché et si les résultats suivent les critères attendus. Ces sources ne définissent pas la gouvernance idéale pour chaque organisation. Cet article propose un inventaire simple, des règles d’entrée et de sortie et une période de retrait contrôlée afin que le catalogue reste compréhensible et maintenable.',
        sources: [oaSkills, skillSpec, oaSkillEval, oaPromptSkills], sections: [
          { title: 'Traiter chaque skill comme un actif maintenu', sourceUrls: [oaSkills.url, skillSpec.url], paragraphs: [
            'Une entrée devrait avoir un propriétaire, un objectif, une portée, une version, une date de revue, des dépendances et des cas qui l’activent ou doivent l’ignorer. Indiquez la procédure principale et les ressources auxiliaires ; le paquet de fichiers ne doit pas masquer les prérequis. La spécification Agent Skills standardise des éléments de structure et de métadonnées, mais elle ne garantit pas qu’un catalogue contient des instructions utiles ou à jour. Une description explicite aide les personnes à comprendre pourquoi le skill existe avant même d’examiner son contenu.',
            'Fixez une règle d’entrée : quel besoin récurrent justifie un skill séparé, quelle preuve montre que l’instruction est utile, et quel responsable acceptera de la maintenir ? Les connaissances génériques déjà acquises par le modèle peuvent rendre certaines règles inutiles ; les consignes trop larges peuvent entrer en conflit avec d’autres. Commencez petit et séparez procédures ayant des déclencheurs, outils ou risques différents. Le catalogue n’est pas un endroit pour archiver chaque prompt essayé.'
          ] },
          { title: 'Repérer doublons et conflits', paragraphs: [
            'Recherchez les skills qui partagent un même déclencheur, outil, artefact de sortie ou domaine métier. Comparez leurs conditions d’activation, leurs instructions principales et les fichiers annexes. Deux skills ne sont pas forcément redondants parce qu’ils mentionnent le même mot ; il faut vérifier si leur responsabilité se recouvre. À l’inverse, deux noms différents peuvent provoquer des instructions concurrentes sur la même tâche. Une revue humaine périodique peut comparer les descriptions et demander aux utilisateurs de signaler un mauvais déclenchement ou une procédure introuvable.',
            'Utilisez des essais d’activation : une tâche cible devrait charger la procédure pertinente, tandis qu’une tâche proche hors périmètre devrait l’éviter. Inspectez les traces et les appels d’outils. OpenAI propose pour l’évaluation des skills de mesurer notamment l’invocation, les commandes exécutées et la conformité de sortie. Ce protocole est décrit pour Codex ; appliquez l’idée de mesure, pas les mécanismes spécifiques à une autre plateforme. Un faible taux d’utilisation seul ne justifie pas une suppression si les tâches ciblées sont rares mais essentielles.'
          ] },
          { title: 'Décider avec une règle de maintien', sourceUrls: [oaSkillEval.url], paragraphs: [
            'Classez chaque skill : actif, à revoir, fusion candidate, remplacé ou retiré. La fréquence d’activation peut être utile, mais elle doit être lue avec importance, taux de réussite, risques et coûts de maintenance. Une procédure très rarement appelée peut être précieuse pour une opération à enjeu. Une procédure fréquemment appelée mais ambiguë devrait être améliorée, pas conservée au seul motif qu’elle est populaire. Gardez des critères qualitatifs et quantitatifs proportionnés au catalogue, et évitez un score global qui masquerait les défauts critiques.',
            'Pour un changement important, conservez quelques cas de régression : activation correcte, non-activation attendue, conflit, outil absent et demande ambiguë. Comparez la variante proposée avec l’ancienne sur les mêmes entrées. Si le skill dépend d’une fonction éphémère, d’une version d’API ou d’un processus organisationnel, inscrivez une date de validité ou un événement de revue. Cela réduit les consignes oubliées qui continuent d’influencer des tâches après que leur contexte a disparu.'
          ] },
          { title: 'Exemple fictif : fusionner deux skills de préparation', paragraphs: [
            'Exemple fictif : un catalogue comprend « préparer le compte rendu » et « mettre en forme le compte rendu », tous deux déclenchés par des demandes de réunion. L’équipe constate que le premier collecte décisions et actions tandis que le second ne modifie que la structure finale. Elle écrit des cas qui demandent uniquement une synthèse, uniquement une mise en page, et les deux à la fois. Puis elle teste une version fusionnée avec un déclencheur plus explicite et une procédure en deux parties.',
            'Si la version fusionnée traite correctement les trois cas sans faire apparaître des instructions de mise en page dans une tâche de synthèse simple, elle peut être essayée sur un périmètre limité. Sinon, les deux compétences restent séparées avec descriptions affinées. Après une période de retour, l’ancienne version peut être retirée et conservée dans l’historique. L’exemple est fictif : il ne décrit pas une bibliothèque réelle ni une comparaison effectuée.'
          ] },
          { title: 'Retirer sans perdre une capacité nécessaire', paragraphs: [
            'Un retrait sûr commence par identifier les fichiers et workflows qui référencent le skill, prévenir ses utilisateurs et choisir une date d’effet. Désactivez d’abord son chargement ou déplacez-le dans une archive non découvrable, puis surveillez les demandes manquées et les éventuels nouveaux conflits. Gardez une version restaurable, les raisons du retrait et un propriétaire de retour arrière. Si une automatisation appelle explicitement le paquet, cette dépendance doit être migrée avant le retrait du fichier ; une suppression isolée peut créer un échec silencieux.',
            'Les compétences obsolètes peuvent être retirées parce que leur outil n’existe plus, que la procédure est couverte par une autre, que le besoin a disparu ou que des tests montrent une dégradation. L’objectif n’est pas de minimiser le nombre de skills à tout prix. Il est de garder un ensemble dont chaque élément a une raison d’être, des limites et un chemin de sortie. Une bibliothèque bien curée sait expliquer pourquoi elle conserve aussi bien que pourquoi elle retire.'
          ] }
        ], takeaway: 'Attribuez un propriétaire et une preuve à chaque skill. Comparez les déclencheurs, révisez les doublons, puis retirez par étapes avec une voie de retour.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'curate-a-skill-library-by-retiring-skills', title: 'Why a skill library must know how to remove skills',
        description: 'Prevent redundant and conflicting instructions with an inventory, evaluation, and reversible retirement process.', category: 'Operations & R&D',
        introduction: 'Adding a reusable instruction is easy; removing one often requires more confidence. Skill libraries accumulate duplicates, outdated procedures, overlapping descriptions, and instructions that rarely activate. OpenAI documentation presents skills as bundles of procedures and resources, while the Agent Skills standard describes a shared structure. OpenAI also recommends evaluating whether a skill was invoked and whether results met expected criteria. These sources do not define ideal governance for every organization. This article proposes a simple inventory, entry and exit rules, and a controlled retirement period so the catalogue stays understandable and maintainable.',
        sources: [oaSkills, skillSpec, oaSkillEval, oaPromptSkills], sections: [
          { title: 'Treat each skill as a maintained asset', sourceUrls: [oaSkills.url, skillSpec.url], paragraphs: [
            'Each entry should have an owner, purpose, scope, version, review date, dependencies, and cases that should activate or ignore it. State the main procedure and supporting resources; a file bundle should not hide prerequisites. The Agent Skills specification standardizes structural and metadata elements, but it does not guarantee that a catalogue contains useful or current instructions. A clear description helps people understand why the skill exists before reading its contents.',
            'Set an entry rule: what recurring need justifies a separate skill, what evidence shows that the instruction helps, and who will maintain it? Generic knowledge the model already has may make some rules unnecessary; broad instructions can conflict with others. Start small and separate procedures with different triggers, tools, or risks. The catalogue is not an archive for every prompt someone tried.'
          ] },
          { title: 'Find duplicates and conflicts', paragraphs: [
            'Search for skills that share a trigger, tool, output artifact, or business domain. Compare activation conditions, primary instructions, and supporting files. Two skills are not necessarily redundant because they mention the same word; check whether their responsibilities overlap. Conversely, different names may still produce competing instructions for one task. A periodic human review can compare descriptions and let users report wrong activation or a procedure they cannot find.',
            'Use activation trials: a target task should load the relevant procedure while a nearby out-of-scope task should avoid it. Inspect traces and tool calls. OpenAI’s skill-evaluation guidance proposes measuring invocation, commands run, and output compliance. That protocol is described for Codex; apply the measurement idea, not mechanisms specific to another platform. Low usage alone is not a reason to delete a skill if its target tasks are rare but essential.'
          ] },
          { title: 'Use a retention rule', sourceUrls: [oaSkillEval.url], paragraphs: [
            'Classify each skill as active, needs review, candidate for merge, replaced, or retired. Invocation frequency may help, but read it alongside importance, success, risk, and maintenance cost. A rarely used procedure can be valuable for a high-stakes operation. A frequently invoked but ambiguous one should be improved rather than retained only because it is popular. Keep qualitative and quantitative criteria proportionate to the catalogue, and avoid one total score that hides critical defects.',
            'For a meaningful change, keep regression cases: correct activation, expected non-activation, conflict, missing tool, and ambiguous request. Compare the proposed version with the old one on identical inputs. If the skill depends on a transient feature, API version, or organizational process, set an expiry date or review event. This reduces forgotten instructions that keep influencing tasks after their context has vanished.'
          ] },
          { title: 'Hypothetical example: merge two preparation skills', paragraphs: [
            'Hypothetical example: a catalogue has “prepare meeting notes” and “format meeting notes,” both triggered by meeting requests. The team finds that the first captures decisions and actions while the second only changes final structure. It writes cases asking for a summary alone, formatting alone, and both. Then it tests a merged version with a clearer trigger and a two-part procedure.',
            'If the merged version handles all three cases without surfacing formatting instructions in a simple summary task, it can be tried in a limited scope. Otherwise, keep the two capabilities separate with refined descriptions. After a feedback period, retire the old version while preserving history. This example is fictional; it describes no real library or completed comparison.'
          ] },
          { title: 'Retire without losing a necessary capability', paragraphs: [
            'Safe retirement starts by identifying files and workflows that reference the skill, notifying users, and choosing an effective date. First disable loading or move it into a non-discoverable archive, then monitor missed requests and any new conflicts. Keep a restorable version, reason for retirement, and rollback owner. If an automation explicitly calls the package, migrate that dependency before removing the file; deleting it in isolation may cause silent failure.',
            'Skills may be retired because their tool no longer exists, another procedure covers the work, the need has ended, or tests show degradation. The goal is not to minimize the number of skills at any cost. It is to keep a set where every item has a purpose, limits, and exit path. A well-curated library can explain why it retains a skill as clearly as why it removes one.'
          ] }
        ], takeaway: 'Give every skill an owner and evidence. Compare triggers, review duplicates, and retire in stages with a rollback path.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'technology-watch-catalogue', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'veille-catalogue-decisions-technologiques', title: 'Organiser sa veille : un catalogue de décisions plutôt qu’une collection d’outils',
        description: 'Transformez votre veille technologique en décisions datées, révisables et reliées aux besoins réels.', category: 'Exploitation & R&D',
        introduction: 'Une liste d’outils accumule vite des noms sans expliquer pourquoi ils ont été retenus, pour quel usage, ni quand réexaminer le choix. Une veille utile est un système de décisions : chaque entrée relie un besoin concret à une option, aux éléments consultés, à une prochaine action et à une date de révision. Cette approche évite que la nouveauté devienne une obligation d’essayer tout produit annoncé. Les guides de conception d’agents d’OpenAI et d’Anthropic recommandent de commencer par une solution proportionnée au travail, puis d’ajouter de la complexité si elle répond à un échec observé. Le catalogue ci-dessous applique cette logique à la veille elle-même, sans faire d’un fournisseur ou d’un framework une référence universelle.',
        sources: [oaGuide, anthAgents, codexGuide, skillSpec, simonAbout], sections: [
          { title: 'Partir d’une question de décision', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'N’ouvrez pas une fiche pour chaque annonce. Commencez par une question qui mérite une réponse : faut-il automatiser une tâche récurrente, remplacer une dépendance, améliorer la reprise après erreur ou réduire le temps de revue ? Décrivez la situation actuelle et le coût observable de son maintien. Si aucun besoin, risque ou échéance ne dépend de la réponse, l’élément peut rester dans une liste de lecture personnelle au lieu d’entrer dans le catalogue opérationnel.',
            'Une même technologie peut être pertinente pour un prototype et inadaptée à un service qui doit reprendre après panne. Notez le contexte : équipe, contraintes d’hébergement, catégories de données, compétences nécessaires et intégrations. Les recommandations des laboratoires sur la simplicité sont des guides d’architecture attribués à leurs auteurs, non des preuves qu’un workflow suffit toujours. Le catalogue aide précisément à rendre explicite quand une nouvelle capacité mérite d’être examinée.'
          ] },
          { title: 'Donner à chaque entrée un statut et une date', paragraphs: [
            'Utilisez des états compréhensibles : repérée, à vérifier, essai autorisé, retenue pour un périmètre, écartée ou archivée. Ajoutez le propriétaire de la décision, les liens vers la documentation primaire et la date de consultation. Séparez « l’éditeur annonce cette fonction » de « l’équipe l’a vérifiée dans un contexte donné ». Une page de documentation peut changer ; une note datée permet de distinguer les connaissances actuelles des captures historiques sans prétendre qu’un produit reste inchangé.',
            'Ajoutez aussi une condition de sortie. Une option retenue peut être réévaluée à l’échéance du contrat, quand un modèle change, quand le volume dépasse une limite ou si un incident révèle une lacune. Une technologie rejetée peut être réouverte si une contrainte évolue, mais le motif du rejet évite de répéter l’enquête. Archivez plutôt que supprimer : la décision passée est utile pour expliquer un choix, mais elle ne doit pas être présentée comme une recommandation actuelle.'
          ] },
          { title: 'Comparer ce qui répond à la même question', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'Une comparaison n’a de sens que si les options partagent un périmètre. Pour un agent, vérifiez d’abord si la tâche a réellement besoin de choix dynamiques ou si un workflow déterministe répond à l’exigence. Si plusieurs options restent pertinentes, comparez leurs comportements sur les mêmes cas : intégration, contrôle des permissions, traces, gestion d’état, reprise, coût d’exploitation et facilité de sortie. Évitez les colonnes de fonctionnalités sans lien avec la décision. La démonstration d’un éditeur prouve qu’un scénario a été présenté, pas qu’il satisfait vos contraintes.',
            'Gardez les faits et les jugements séparés. « La documentation décrit une interface de reprise » est une observation sur un document ; « cette interface convient à notre service » est une conclusion à vérifier. Laissez une case « inconnue » au lieu de déduire une capacité d’une ressemblance de vocabulaire. Quand la documentation décrit seulement une plateforme ou une version, notez ce périmètre. Cette discipline est particulièrement importante lorsque les produits partagent des mots comme agent, skill ou trace, mais exécutent les consignes différemment.'
          ] },
          { title: 'Exemple fictif : décider d’étudier un orchestrateur', paragraphs: [
            'Exemple fictif : une petite équipe traite des demandes qui suivent un parcours stable, mais hésite à adopter un orchestrateur d’agents annoncé récemment. La fiche commence par le problème vérifiable : deux étapes échouent à reprendre après interruption, et la reprise manuelle est documentée comme une tâche répétitive. Elle note trois options : améliorer le workflow actuel, essayer un orchestrateur dans un environnement synthétique, ou attendre. Pour chacune, l’équipe fixe une preuve attendue, les limites de sécurité, un responsable et une date de revue.',
            'L’entrée ne conclut pas que l’orchestrateur est « le meilleur ». Elle établit un essai borné : rejouer des cas fictifs avec interruption injectée, vérifier l’état récupéré, inspecter les traces et estimer l’effort d’exploitation. Si le mécanisme de reprise n’est pas documenté ou observable, la fiche marque l’inconnue et ne passe pas en adoption. C’est un exemple construit pour expliquer le catalogue ; aucun produit réel, essai ou résultat d’entreprise n’est décrit.'
          ] },
          { title: 'Examiner la provenance des recommandations', sourceUrls: [simonAbout.url], paragraphs: [
            'Une recommandation publique peut aider à découvrir une source ou un sujet, mais elle ne mesure ni sa fiabilité ni sa représentativité. Suivez le lien vers la page officielle, le dépôt, l’auteur ou le standard, puis distinguez ce que la source dit d’elle-même de ce qui a été vérifié ailleurs. À titre d’exemple, la page de Simon Willison présente plusieurs flux de publication et expose ses liens de financement, invitations à des previews et autres intérêts. Ces informations rendent la provenance plus lisible, mais elles ne garantissent pas la justesse de chaque billet.',
            'Le catalogue peut conserver le fil de découverte et la référence primaire côte à côte : « signal communautaire » pour l’origine de la piste, « source officielle lue » pour ce qui soutient la décision. Les commentaires et votes d’une communauté restent des signaux éditoriaux auto-sélectionnés ; ils ne prouvent ni une compétence particulière ni un accord général. Cette séparation aide l’équipe à ne pas transformer une recommandation répétée en fait technique, et facilite une vérification indépendante quand la décision a des conséquences.'
          ] },
          { title: 'Faire de la veille un rythme léger', paragraphs: [
            'Un catalogue trop détaillé devient un deuxième travail de gestion. Limitez les champs au minimum qui soutient une décision : besoin, option, preuve ou incertitude, contraintes, responsable, statut et prochaine date. Faites une courte revue régulière des entrées proches de leur échéance, pas une lecture exhaustive de toutes les annonces. Les pages de fournisseurs, standards et autorités donnent des informations de nature différente ; indiquez leur provenance et ne confondez pas un billet marketing avec une spécification ou un retour indépendant.',
            'Cette méthode convient aux équipes qui font des choix technologiques avec des conséquences de maintenance ou de sécurité. Elle est excessive pour une curiosité sans coût ni engagement : une liste personnelle suffit alors. Le bénéfice recherché n’est pas une veille plus volumineuse, mais une meilleure mémoire des raisons et des seuils de changement. Une bonne fiche peut se conclure par « pas d’action pour l’instant », avec un déclencheur précis pour y revenir. C’est une décision à part entière et souvent la plus économique.'
          ] }
        ], takeaway: 'Reliez chaque option à une question métier, à une preuve, à un responsable et à une date de révision. Une veille réussie sait aussi documenter pourquoi elle n’adopte rien.', service: { href: '/pilotage-projet-complexe/', label: 'Découvrir le pilotage de projets complexes' }
      },
      en: {
        slug: 'technology-watch-as-a-decision-catalogue', title: 'Organize technology watch as a decision catalogue, not a tool collection',
        description: 'Turn technology watch into dated decisions that can be reviewed against real needs.', category: 'Operations & R&D',
        introduction: 'A list of tools quickly accumulates names without explaining why they were selected, what they are for, or when to revisit the choice. Useful technology watch is a decision system: each entry links a concrete need to an option, the evidence reviewed, a next action, and a review date. This prevents novelty from becoming an obligation to try every announced product. OpenAI and Anthropic agent-design guides recommend starting with a solution proportionate to the work and adding complexity when it addresses an observed failure. The catalogue below applies that logic to technology watch itself without making any vendor or framework a universal reference.',
        sources: [oaGuide, anthAgents, codexGuide, skillSpec, simonAbout], sections: [
          { title: 'Start with a decision question', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'Do not open a record for every announcement. Start with a question worth answering: should a recurring task be automated, a dependency replaced, recovery after failure improved, or review time reduced? Describe the current situation and the observable cost of keeping it. If no need, risk, or deadline depends on the answer, the item can stay on a personal reading list instead of entering the operational catalogue.',
            'The same technology may suit a prototype and fail a service that must recover after an outage. Record context: team, hosting constraints, data classes, required skills, and integrations. The labs’ simplicity recommendations are architecture guidance attributed to their authors, not proof that a workflow is always enough. The catalogue makes it explicit when a new capability merits investigation.'
          ] },
          { title: 'Give every entry a status and date', paragraphs: [
            'Use understandable states: noticed, needs verification, approved trial, retained for a scope, rejected, or archived. Add the decision owner, links to primary documentation, and the date reviewed. Separate “the vendor announces this feature” from “the team verified it in a given context.” Documentation can change; a dated note separates current knowledge from historical snapshots without pretending that a product stays unchanged.',
            'Also define an exit condition. A selected option can be reviewed at contract renewal, after a model change, when volume crosses a limit, or if an incident exposes a gap. A rejected technology can be reopened if a constraint changes, while the rejection reason prevents repeating the investigation. Archive instead of deleting: past decisions help explain a choice, but should not appear to be current recommendations.'
          ] },
          { title: 'Compare options that answer the same question', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'A comparison only makes sense when options share a scope. For an agent, first check whether the task actually needs dynamic choices or whether a deterministic workflow meets the requirement. If several options remain viable, compare behavior on the same cases: integration, permission controls, traces, state management, recovery, operating cost, and ease of exit. Avoid feature columns unrelated to the decision. A vendor demo proves a scenario was presented, not that it meets your constraints.',
            'Keep facts and judgments separate. “The documentation describes a recovery interface” is an observation about a document; “this interface suits our service” is a conclusion to verify. Leave an “unknown” field instead of inferring a capability from similar vocabulary. When documentation only describes one platform or version, record that scope. This matters when products share words such as agent, skill, or trace but execute instructions differently.'
          ] },
          { title: 'Hypothetical example: decide whether to assess an orchestrator', paragraphs: [
            'Hypothetical example: a small team handles requests that follow a stable path but is considering a recently announced agent orchestrator. The record starts with a verifiable problem: two steps fail to resume after interruption, and manual recovery is documented as repetitive work. It lists three options: improve the current workflow, try an orchestrator in a synthetic environment, or wait. For each, the team defines expected evidence, safety limits, an owner, and a review date.',
            'The record does not conclude that the orchestrator is “best.” It defines a bounded trial: replay fictional cases with injected interruption, inspect recovered state and traces, and estimate operating effort. If recovery is undocumented or unobservable, the record marks the unknown and does not move to adoption. This is a constructed example to explain the catalogue; it describes no real product, trial, or business outcome.'
          ] },
          { title: 'Trace recommendations to their sources', sourceUrls: [simonAbout.url], paragraphs: [
            'A public recommendation can help discover a source or topic, but it does not measure reliability or representativeness. Follow the link to an official page, repository, author, or standard, then separate what the source says about itself from what has been independently checked. For example, Simon Willison’s about page lists publication feeds and discloses sponsorship, product-preview invitations, and other interests. This makes provenance easier to inspect but does not guarantee that every post is correct.',
            'The catalogue can keep the discovery thread and primary reference side by side: “community signal” for how the lead surfaced and “official source read” for what supports the decision. Community comments and votes remain self-selected editorial signals; they do not prove special expertise or general agreement. This separation prevents a repeated recommendation from becoming a technical fact and makes independent review easier when a decision has consequences.'
          ] },
          { title: 'Keep technology watch lightweight', paragraphs: [
            'An overly detailed catalogue becomes another management job. Keep only fields that support a decision: need, option, evidence or uncertainty, constraints, owner, status, and next date. Hold a short periodic review of entries nearing their deadline rather than reading every announcement exhaustively. Vendor pages, standards, and regulators offer different kinds of information; record provenance and do not confuse marketing with a specification or independent experience.',
            'This method suits teams making technology choices with maintenance or security consequences. It is excessive for curiosity with no cost or commitment; a personal list is enough. The goal is not more watch activity but a better memory of reasons and change thresholds. A good record can end with “no action for now” and a precise trigger for returning to it. That is a decision in its own right and often the cheapest one.'
          ] }
        ], takeaway: 'Link every option to a business question, evidence, owner, and review date. Good technology watch also records why nothing is being adopted.', service: { href: '/en/project-leadership/', label: 'Explore complex project leadership' }
      }
    }
  },
  {
    id: 'agent-framework-selection', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'choisir-framework-agent-sur-cas-reels', title: 'Comparer les frameworks d’agents sans se limiter à leur démonstration',
        description: 'Évaluez orchestration, état, reprise, observation et dépendance sur un parcours adapté à votre besoin.', category: 'Exploitation & R&D',
        introduction: 'Une démonstration soignée montre souvent le chemin heureux : entrée courte, outil disponible, réponse convaincante. Le choix d’un framework engage pourtant l’équipe sur des questions moins visibles : qui conserve l’état, comment une erreur est reprise, quelles traces sont accessibles, et que faut-il reconstruire pour changer de fournisseur ? Les guides d’OpenAI et d’Anthropic conseillent de choisir une architecture en fonction du travail et d’ajouter de la complexité si l’évaluation le justifie. Le retour d’expérience d’Anthropic sur son système multi-agent expose aussi des problèmes de coordination et de fiabilité propres à ces architectures. Il s’agit de sources d’éditeurs, pas de comparatifs indépendants. Voici une grille de sélection qui met les options à l’épreuve d’un scénario commun.',
        sources: [oaGuide, anthAgents, anthMulti, oaEvals], sections: [
          { title: 'Décrire le besoin avant de comparer', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'Écrivez un parcours représentatif en termes d’entrée, de décisions, d’outils, d’état à modifier et de résultat attendu. Distinguez ce qui est fixe de ce qui doit être choisi dynamiquement. Si les étapes sont connues et les embranchements rares, un workflow explicite peut être plus simple à inspecter qu’un agent libre de choisir à chaque tour. Si l’information disponible transforme le chemin à suivre, l’agent peut se justifier, mais les erreurs possibles doivent être testables. Ce cadrage empêche de sélectionner un framework seulement parce qu’il rend la démo spectaculaire.',
            'Formulez des contraintes de service : environnement d’exécution, secrets, identité, limites de réseau, exigences d’audit, charge attendue, budget et compétences de maintenance. Certaines exigences ne se comparent pas par une capture d’écran. Faites une liste de critères éliminatoires avant les critères de confort. Une option qui ne permet pas de suspendre une action à risque ou d’exporter les données de session peut être éliminée tôt si ces éléments sont des exigences. Le poids attribué à chaque critère est un choix d’équipe, pas une mesure publiée par le fournisseur.'
          ] },
          { title: 'Tester le parcours heureux et les cas de reprise', paragraphs: [
            'Préparez un cas normal, un résultat invalide d’outil, une indisponibilité temporaire, une réponse ambiguë et une action qui exige une autorisation humaine. Notez pour chaque cas l’état initial, la séquence d’événements attendue, la limite de reprises et le résultat acceptable. Vérifiez si le framework expose suffisamment d’information pour comprendre l’échec sans deviner à partir du texte final. Les articles de fournisseurs sur les agents soulignent que les appels d’outils et les transferts rendent le comportement multi-tour plus difficile à évaluer que la réponse isolée.',
            'Un bon test de reprise examine aussi les effets secondaires. Une action peut réussir à la première tentative et être répétée parce que l’accusé de réception est perdu ; si l’opération n’est pas idempotente, une relance aveugle risque de dupliquer le travail. Le framework doit permettre au concepteur de borner les appels, de conserver l’identifiant d’opération ou de faire contrôler une reprise. Ce sont des propriétés d’architecture à vérifier dans la documentation puis dans une maquette contrôlée, pas des capacités qu’on peut inférer du mot « stateful ».'
          ] },
          { title: 'Comparer état, observabilité et frontière d’exécution', sourceUrls: [anthMulti.url, oaEvals.url], paragraphs: [
            'Pour l’état, demandez ce qui survit à un redémarrage, quelle version de conversation est stockée et comment elle est exportée ou supprimée. Pour l’observabilité, vérifiez si l’on peut retrouver l’entrée, les appels d’outils, les décisions de routage, les erreurs et le résultat final avec des identifiants corrélés. Pour l’exécution, regardez où tournent les outils, comment les secrets sont injectés, quelles permissions s’appliquent et si le modèle peut produire des effets externes sans validation. OWASP classe l’agence excessive comme un risque qui peut venir de fonctionnalités, permissions ou autonomie trop larges.',
            'Cherchez aussi les dépendances implicites : formats de session propriétaires, système de files, API de modèle, sérialisation, connecteurs, extensions, registre de traces ou méthode de déploiement. La portabilité du code n’implique pas celle des données et de l’historique. Demandez quelles interfaces sont publiques, documentées et testables, et lesquelles sont des abstractions internes. Un essai sérieux mesure le coût de changer une seule intégration avant d’affirmer que le verrouillage est faible.'
          ] },
          { title: 'Exemple fictif : comparer deux options sur le même incident', paragraphs: [
            'Exemple fictif : une assistance interne doit retrouver une procédure et ouvrir une demande de suivi uniquement après confirmation. Dans un bac à sable, chaque option reçoit le même texte synthétique ; l’outil de recherche renvoie une réponse vide au premier appel, puis un résultat ambigu au second. Le parcours attendu est : signaler l’incertitude, demander confirmation et ne créer aucune demande avant l’accord. L’essai capture les traces et vérifie l’absence d’écriture prématurée. Le tableau note également combien d’étapes ont été nécessaires pour reprendre après une erreur.',
            'Supposons qu’une option rende ses transferts faciles à voir mais nécessite une couche externe pour conserver l’état ; l’autre gère l’état mais cache une partie de la trace. Le résultat n’est pas un podium : l’équipe documente quelle lacune elle accepte, quelles protections compensent cette lacune et quel coût d’exploitation en découle. Toute donnée de score ou de coût serait ici inventée, donc l’exemple reste qualitatif. Il décrit un protocole proposé, pas un test exécuté ni un incident réel.'
          ] },
          { title: 'Utiliser une décision avec un coût de sortie explicite', paragraphs: [
            'Pour chaque critère, consignez la preuve, l’inconnue et la conséquence d’une réponse défavorable. Donnez un poids uniquement si l’équipe peut expliquer pourquoi un critère importe plus qu’un autre. Gardez une section « non testé » visible : elle empêche une documentation marketing ou un prototype de devenir par accident une promesse de production. Faites relire la sélection par les personnes responsables de l’exploitation, de la sécurité et de la conformité selon le périmètre réel.',
            'Un framework spécialisé n’est pas toujours le bon investissement. Un workflow écrit dans le code applicatif peut suffire quand les étapes sont stables, le nombre d’intégrations faible et l’équipe capable de maintenir les contrôles. À l’inverse, une orchestration partagée peut se justifier quand elle réduit une complexité répétée et apporte les mécanismes opératoires requis. Mesurez cette utilité avec le scénario réel et gardez un plan d’export ou de remplacement. Le meilleur choix est celui dont les limites sont visibles et supportables pour la durée prévue.'
          ] }
        ], takeaway: 'Comparez des scénarios identiques, y compris erreur et reprise. Vérifiez la trace, l’état et les permissions, puis chiffrez le coût de sortie avant de choisir.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'select-agent-frameworks-beyond-the-demo', title: 'Compare agent frameworks beyond their demos',
        description: 'Evaluate orchestration, state, recovery, observability, and lock-in against a relevant workflow.', category: 'Operations & R&D',
        introduction: 'A polished demo often shows the happy path: short input, available tool, convincing response. Choosing a framework commits a team to less visible questions: who keeps state, how an error is recovered, what traces are available, and what must be rebuilt to change vendors? OpenAI and Anthropic guides recommend matching architecture to the work and adding complexity when evaluation justifies it. Anthropic’s account of its multi-agent research system also describes coordination and reliability problems specific to such architectures. These are vendor sources, not independent comparisons. This selection grid puts options through a shared scenario.',
        sources: [oaGuide, anthAgents, anthMulti, oaEvals], sections: [
          { title: 'Describe the need before comparing', sourceUrls: [oaGuide.url, anthAgents.url], paragraphs: [
            'Write a representative workflow in terms of input, decisions, tools, state changes, and expected result. Separate what is fixed from what needs to be chosen dynamically. If steps are known and branches are rare, an explicit workflow may be easier to inspect than an agent free to choose at each turn. If new information changes the path, an agent may be justified, but possible failures must be testable. This framing prevents selecting a framework only because it makes a striking demo.',
            'State service constraints: execution environment, secrets, identity, network limits, audit requirements, expected load, budget, and maintenance skills. Some requirements cannot be compared from screenshots. List disqualifying criteria before preferences. An option that cannot pause a risky action or export session data may be eliminated early if those are requirements. Weighting criteria is a team decision, not a score published by the vendor.'
          ] },
          { title: 'Test the happy path and recovery cases', paragraphs: [
            'Prepare a normal case, invalid tool result, temporary outage, ambiguous response, and action requiring human authorization. For each, record initial state, expected event sequence, retry limit, and acceptable outcome. Check whether the framework exposes enough information to understand failure without guessing from the final text. Vendor agent articles note that tool calls and handoffs make multi-turn behavior harder to evaluate than an isolated answer.',
            'A good recovery test also examines side effects. An action may succeed on the first attempt and then be repeated because its acknowledgement was lost; if the operation is not idempotent, a blind retry may duplicate work. The framework should let the designer bound calls, retain an operation identifier, or require a recovery check. These are architecture properties to verify in documentation and a controlled prototype, not capabilities to infer from the word “stateful.”'
          ] },
          { title: 'Compare state, observability, and execution boundaries', sourceUrls: [anthMulti.url, oaEvals.url], paragraphs: [
            'For state, ask what survives restart, which conversation version is stored, and how it is exported or deleted. For observability, verify whether input, tool calls, routing decisions, errors, and final outcome can be found through correlated identifiers. For execution, inspect where tools run, how secrets are injected, which permissions apply, and whether the model can cause external effects without approval. OWASP describes excessive agency as a risk that can result from overly broad functionality, permission, or autonomy.',
            'Look for implicit dependencies too: proprietary session formats, queue systems, model APIs, serialization, connectors, extensions, trace registries, or deployment methods. Portable code does not imply portable data and history. Ask which interfaces are public, documented, and testable, and which are internal abstractions. A serious trial measures the cost of changing one integration before claiming that lock-in is low.'
          ] },
          { title: 'Hypothetical example: compare two options on the same incident', paragraphs: [
            'Hypothetical example: an internal assistant must find a procedure and open a follow-up request only after confirmation. In a sandbox, each option receives the same synthetic text; the search tool returns no answer first, then an ambiguous result. The expected path is to signal uncertainty, ask for confirmation, and create no request before approval. The trial captures traces and checks for premature writes. The comparison also records how many steps were needed to recover from an error.',
            'Suppose one option makes handoffs easy to inspect but requires an external layer to preserve state, while another manages state but hides part of the trace. The result is not a ranking: the team records which gap it accepts, what controls compensate, and what operating cost follows. Any score or cost figure would be invented here, so the example stays qualitative. It describes a proposed protocol, not a trial that ran or a real incident.'
          ] },
          { title: 'Make the exit cost part of the decision', paragraphs: [
            'For every criterion, record evidence, unknowns, and the consequence of an unfavorable answer. Assign a weight only when the team can explain why a criterion matters more. Keep a visible “not tested” section so marketing documentation or a prototype does not accidentally become a production promise. Have the choice reviewed by the people responsible for operations, security, and compliance as relevant to the actual scope.',
            'A specialized framework is not always a good investment. Application code may be enough when steps are stable, integrations are few, and the team can maintain controls. Shared orchestration can make sense when it reduces repeated complexity and supplies required operating mechanisms. Assess its usefulness against the real scenario and retain an export or replacement plan. The best choice is one whose limits are visible and acceptable for the expected duration.'
          ] }
        ], takeaway: 'Compare identical scenarios, including failure and recovery. Check traces, state, and permissions, then estimate exit cost before choosing.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'logs-to-decisions', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'transformer-logs-agent-en-decisions', title: 'Transformer les logs en décisions d’exploitation',
        description: 'Concevez des événements corrélables et minimisés qui aident à diagnostiquer un incident sans aspirer les conversations.', category: 'Exploitation & R&D',
        introduction: 'Un système peut produire des gigaoctets de logs sans permettre de répondre aux questions utiles : quelle exécution a échoué, quel outil a été appelé, et quel état a changé ? La valeur opérationnelle ne vient pas du volume mais de l’association entre événements, traces et décisions possibles. OpenTelemetry explique que la corrélation des logs avec les traces repose sur un contexte d’exécution cohérent, et ses conventions CI/CD recommandent cette corrélation lorsque le contexte est disponible. Ces normes ne définissent pas à elles seules le schéma métier d’un agent. La méthode proposée consiste à partir des questions d’exploitation, choisir quelques événements structurés et vérifier que chaque champ justifie son coût et son risque de confidentialité.',
        sources: [otelLogs, otelCicd, owaspMonitoring, cnilHR], sections: [
          { title: 'Partir d’une décision, pas d’une liste de champs', sourceUrls: [otelLogs.url, owaspMonitoring.url], paragraphs: [
            'Pour chaque signal, demandez : quelle décision changera si cette valeur est connue ? Un identifiant d’exécution peut relier l’entrée, les étapes d’outil et le résultat ; un statut et un code d’erreur peuvent guider une alerte ou un diagnostic. À l’inverse, enregistrer toute conversation « au cas où » n’est pas un plan d’observabilité. Si aucun opérateur ne peut expliquer l’usage d’un champ, il risque de devenir une charge de stockage et de protection des données sans bénéfice défini.',
            'Dessinez le parcours d’exécution avant d’instrumenter : réception, décision, appel d’outil, transfert, reprise, résultat. Repérez les frontières entre composants où les logs se perdent ou les identifiants changent. OpenTelemetry décrit le contexte de trace comme un moyen de relier des événements de plusieurs composants. Faites un essai de bout en bout pour vérifier qu’un opérateur peut retrouver la séquence par identifiant, pas seulement par heure approximative.'
          ] },
          { title: 'Adopter un événement lisible et stable', paragraphs: [
            'Un événement structuré sépare nom, horodatage, niveau, composant et attributs typés. Pour un appel d’outil, cela pourrait inclure l’outil, le résultat (succès, erreur ou refus), la durée, un identifiant de trace et un identifiant de tâche non directement parlant pour un humain. Choisissez des noms et valeurs limités ; un champ libre tel que « description complète du contexte » devient vite imprévisible. Les conventions générales d’OpenTelemetry cherchent à rendre les attributs cohérents entre langages et services, tandis que les conventions CI/CD restent spécifiques à ce domaine et ont un statut de maturité indiqué par le standard.',
            'Consignez les événements de changement d’état séparément des diagnostics textuels. Un message « terminé » n’établit pas nécessairement que l’action a été appliquée dans le système cible. Pour les effets externes, distinguez demande, confirmation reçue et résultat vérifié. Un identifiant d’opération permet de relier ces étapes sans exposer tout le contenu utilisateur. Documentez les champs obligatoires, facultatifs et les changements de version pour que les tableaux de bord n’interprètent pas une valeur nouvelle comme un échec ancien.'
          ] },
          { title: 'Corréler sans recopier les données sensibles', sourceUrls: [otelLogs.url, cnilHR.url], paragraphs: [
            'La corrélation n’exige pas de copier le prompt entier dans chaque ligne. Utilisez des identifiants opaques, un lien vers un stockage d’accès contrôlé, une durée de conservation adaptée et des rôles d’accès séparés. Réfléchissez aux secrets présents dans les réponses d’outils, aux données personnelles dans les messages et au contenu injecté par un tiers. Les recommandations de l’OpenTelemetry décrivent des identifiants de trace et de span pour relier des données d’observabilité ; elles ne prescrivent pas que le texte brut d’une requête soit journalisé.',
            'L’équipe doit décider qui accède aux traces, pour quelle finalité et combien de temps. Pour un incident, il peut suffire de stocker métadonnées et codes, puis d’accéder à un contenu détaillé selon une procédure habilitée. La CNIL rappelle, dans son guide de gestion du personnel, la sécurité, la limitation des accès et la traçabilité des actions sur les informations. Les obligations précises dépendent du contexte : une bonne conception technique réduit la collecte mais ne remplace pas une analyse de conformité.'
          ] },
          { title: 'Exemple fictif : investiguer une boucle de recherche', paragraphs: [
            'Exemple fictif : un agent de recherche appelle plusieurs fois le même outil sans produire de réponse. Un événement de début de tâche contient un identifiant, la version du workflow et la catégorie d’entrée ; chaque appel contient numéro d’étape, nom d’outil, durée et classe de résultat ; l’événement final indique succès, abandon ou transfert à une personne. Les arguments bruts et le texte documentaire ne sont pas enregistrés par défaut. Un tableau de bord regroupe les traces par version et classe d’erreur afin qu’un opérateur puisse localiser le premier appel répétitif.',
            'La première hypothèse est que l’outil retourne un résultat vide et que l’agent ignore le signal. L’opérateur compare les événements de la trace, puis examine un échantillon de contenu uniquement s’il est nécessaire et autorisé. La correction possible serait de renvoyer une erreur typée ou de fixer une règle d’arrêt, mais l’exemple ne prétend pas qu’une panne réelle a été observée ni qu’une modification a été faite. Il montre une chaîne enquête-décision vérifiable, pas une recette universelle.'
          ] },
          { title: 'Maintenir la télémétrie comme un produit', paragraphs: [
            'Testez la télémétrie avec les mêmes scénarios que le service : erreur d’outil, timeout, arrêt volontaire, action refusée et réussite. Pour chaque cas, vérifiez que l’alerte est compréhensible, que les événements ont une corrélation et qu’aucune donnée interdite n’est exportée. Mesurez aussi les coûts de cardinalité : un identifiant utilisateur libre utilisé comme dimension d’agrégation peut produire des séries infinies et rendre les indicateurs inutilisables. Revoir les champs à chaque changement de schéma est moins lourd que maintenir des tableaux de bord basés sur des conventions oubliées.',
            'Cette approche convient aux systèmes où une panne ou une action externe doit être diagnostiquée. Un prototype local peut se contenter d’un journal sobre. Dans tous les cas, chaque donnée collectée devrait répondre à une question d’exploitation, de sécurité ou de conformité clairement assignée. Les logs ne deviennent pas une décision automatiquement : ils fournissent un contexte à une personne ou à une règle d’alerte, qui peut ensuite déclencher une vérification, un rollback ou une pause. Cette dernière étape doit être conçue et autorisée séparément.'
          ] }
        ], takeaway: 'Définissez d’abord la décision à soutenir. Corrélez des événements structurés, limitez le contenu conservé et testez les traces sur des scénarios d’échec réels ou synthétiques.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'turn-agent-logs-into-operational-decisions', title: 'Turn logs into operational decisions',
        description: 'Design correlated, minimized events that help diagnose incidents without collecting full conversations.', category: 'Operations & R&D',
        introduction: 'A system can produce gigabytes of logs and still fail to answer useful questions: which run failed, which tool was called, and what state changed? Operational value comes from linking events, traces, and possible decisions, not from volume. OpenTelemetry explains that log correlation with traces relies on a consistent execution context, and its CI/CD conventions recommend correlation when that context is available. These standards do not define an agent’s business schema on their own. The proposed method starts from operational questions, selects a few structured events, then checks that every field justifies its cost and privacy risk.',
        sources: [otelLogs, otelCicd, owaspMonitoring, cnilHR], sections: [
          { title: 'Start with a decision, not a field list', sourceUrls: [otelLogs.url, owaspMonitoring.url], paragraphs: [
            'For each signal, ask: what decision changes if this value is known? A run identifier can link input, tool steps, and outcome; a status and error code may guide an alert or diagnosis. By contrast, recording every conversation “just in case” is not an observability plan. If no operator can explain how a field will be used, it may become storage and data-protection overhead with no defined benefit.',
            'Sketch the execution path before instrumenting: intake, decision, tool call, handoff, retry, outcome. Find component boundaries where logs are lost or identifiers change. OpenTelemetry describes trace context as a way to connect events from multiple components. Run an end-to-end test to verify that an operator can retrieve the sequence by identifier, not only by approximate time.'
          ] },
          { title: 'Use stable, readable events', paragraphs: [
            'A structured event separates name, timestamp, level, component, and typed attributes. A tool call might include tool name, result (success, error, or denial), duration, trace identifier, and an opaque task identifier. Choose bounded names and values; a free-text field such as “full context description” quickly becomes unpredictable. OpenTelemetry’s general conventions aim for consistency across languages and services, while its CI/CD conventions are specific to that domain and have a maturity status stated by the standard.',
            'Record state transitions separately from diagnostic text. A “done” message does not necessarily prove that an action was applied in the target system. For external effects, distinguish request, acknowledgement, and verified outcome. An operation ID can link these steps without exposing all user content. Document required and optional fields and schema changes so dashboards do not interpret a new value as an old failure.'
          ] },
          { title: 'Correlate without copying sensitive data', sourceUrls: [otelLogs.url, cnilHR.url], paragraphs: [
            'Correlation does not require copying the full prompt into each line. Use opaque identifiers, a link to access-controlled storage, an appropriate retention period, and separate access roles. Consider secrets in tool results, personal data in messages, and content injected by third parties. OpenTelemetry recommendations describe trace and span IDs for linking observability data; they do not require logging raw request text.',
            'The team should decide who can access traces, for which purpose, and for how long. For an incident, metadata and codes may be enough, with detailed content accessed under an authorized procedure. CNIL guidance on personnel data management recalls security, access limits, and traceability of actions on information. Specific obligations depend on context: sound technical design can reduce collection but does not replace a compliance assessment.'
          ] },
          { title: 'Hypothetical example: investigate a search loop', paragraphs: [
            'Hypothetical example: a research agent calls the same tool repeatedly without producing an answer. A task-start event contains an ID, workflow version, and input category; each call records step number, tool name, duration, and result class; the final event says success, abandonment, or handoff. Raw arguments and document text are not recorded by default. A dashboard groups traces by version and error class so an operator can find the first repeated call.',
            'The first hypothesis is that the tool returns an empty result and the agent ignores the signal. The operator compares trace events, then inspects a content sample only if necessary and authorized. A possible fix would be a typed error or a stop rule, but this example does not claim that a real fault occurred or a change was made. It shows a verifiable investigation-to-decision chain, not a universal recipe.'
          ] },
          { title: 'Maintain telemetry as a product', paragraphs: [
            'Test telemetry with the same scenarios as the service: tool error, timeout, intentional stop, denied action, and success. For each, check that the alert is understandable, events correlate, and no prohibited data is exported. Also measure cardinality costs: using a free-form user ID as a metric dimension may create unbounded series and make indicators unusable. Revisiting fields with each schema change is easier than maintaining dashboards based on forgotten conventions.',
            'This approach suits systems where outages or external actions must be diagnosed. A local prototype may need only a modest log. In every case, collected data should answer a clearly assigned operational, security, or compliance question. Logs do not become a decision automatically: they provide context to a person or alert rule, which may then trigger verification, rollback, or pause. That final action must be designed and authorized separately.'
          ] }
        ], takeaway: 'Define the decision first. Correlate structured events, limit retained content, and test traces against real or synthetic failure scenarios.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'agent-field-reliability', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'fiabilite-agent-en-production', title: 'Évaluer un agent en conditions réelles : réussite, reprises et supervision',
        description: 'Suivez la fiabilité d’un agent comme un service dans la durée, avec ses reprises, ses erreurs et ses transferts.', category: 'Exploitation & R&D',
        introduction: 'Un benchmark pré-déploiement répond à une question limitée sur un ensemble de tâches ; il ne dit pas à lui seul comment un agent se comporte lorsque les entrées, outils et dépendances changent. La fiabilité de terrain porte sur la qualité du service pendant une période : résultats vérifiés, reprises, transferts, délais, coûts et incidents. Les ressources d’évaluation d’Anthropic et d’OpenAI mettent l’accent sur traces, résultats finaux et répétabilité ; OWASP rappelle que les séquences d’actions peuvent révéler des écarts que la disponibilité seule ne montre pas. Ces pages sont des guides d’éditeurs et d’un projet de sécurité, pas une norme complète. Voici un tableau de bord proposé qui distingue qualité produit, disponibilité et supervision humaine.',
        sources: [anthEvals, oaEvals, owaspMonitoring, owaspExcess], sections: [
          { title: 'Définir ce que signifie « réussi »', sourceUrls: [anthEvals.url, oaEvals.url], paragraphs: [
            'Décrivez l’unité de travail que l’agent doit terminer et l’état qui prouve sa réussite. Une réponse fluide n’est pas nécessairement une action réalisée : une demande de réservation exige que la réservation existe, un résumé documentaire doit être lié aux sources consultées, et une modification de données doit satisfaire des invariants. Séparez le résultat acceptable, les critères de qualité, les actions interdites et les cas où l’agent doit s’abstenir ou transférer à une personne.',
            'Construisez quelques classes de tâches avant le lancement : fréquent, ambigu, données manquantes, outil temporairement indisponible et action à impact élevé. Les evals hors production peuvent aider à repérer des régressions, mais les comportements observés en service dépendent aussi de l’environnement. Les guides officiels décrivent tâches, traces, graders et état final comme pièces d’un dispositif d’évaluation. Utilisez-les comme repères ; choisissez les critères avec les personnes responsables du résultat métier.'
          ] },
          { title: 'Mesurer un flux de bout en bout', paragraphs: [
            'Suivez au minimum le nombre de tâches reçues, terminées, transférées et abandonnées, ainsi que la proportion qui passe une vérification de résultat. Ajoutez les délais de bout en bout, le temps humain de reprise, les appels d’outils, les reprises et le coût si disponible. Montrez le dénominateur et le périmètre de chaque indicateur : « taux de réussite » sans définition des cas, période et sorties exclues est ambigu. Comparez des tâches semblables plutôt que de mélanger opérations simples et cas rares mais risqués.',
            'Le service peut avoir un bon taux moyen et un sous-groupe défaillant. Examinez les catégories d’entrées, versions du modèle et de l’agent, outils, intégrations et résultats de transfert, en évitant une collecte qui n’a pas de justification. Étiquetez les changements de configuration et les périodes de maintenance. Lorsque les cas sont peu nombreux, présentez les nombres observés et l’incertitude plutôt qu’un pourcentage très précis. Ne transformez pas une variation courte en affirmation de dérive sans vérifier saisonnalité, échantillon et changement amont.'
          ] },
          { title: 'Observer les traces et les reprises', sourceUrls: [owaspMonitoring.url, anthEvals.url], paragraphs: [
            'Pour un échantillon de tâches, reliez demande, décisions d’outil, résultats intermédiaires, erreurs, transferts et état final. Il faut pouvoir distinguer une reprise réussie d’un retry répété qui a créé un effet secondaire. OWASP recommande de surveiller les outils appelés, leur ordre, leur fréquence et leurs paramètres afin de repérer des séquences atypiques. Ce suivi se conçoit avec des identifiants et une politique de conservation : l’observabilité ne nécessite pas de rendre toutes les conversations accessibles à toute l’équipe.',
            'Documentez les conditions qui déclenchent une alerte ou une intervention : hausse d’erreurs vérifiées, actions refusées, outil indisponible, dépassement du budget d’appels ou état final incohérent. Une alerte devrait nommer le propriétaire et la réponse attendue, par exemple suspendre un connecteur et faire traiter la file manuellement. Les seuils sont propres au service ; ils ne se copient pas d’un article fournisseur. Le contrôle doit aussi être testé pour éviter les alertes non actionnables ou le silence face à une erreur de comportement.'
          ] },
          { title: 'Exemple fictif : analyser les demandes incomplètes', paragraphs: [
            'Exemple fictif : un agent classe des formulaires synthétiques et transmet les cas incertains à une personne. Le tableau de bord distingue formulaires acceptés par un contrôle de cohérence, refusés pour données insuffisantes, transférés et erreurs d’outil. Sur un lot fictif de 40 demandes, dix comportent un champ manquant ; une vérification humaine confirme lesquelles auraient dû être transférées. On examine aussi les traces d’une semaine pour repérer un changement après mise à jour de la description d’un outil. Ce nombre est un élément de scénario, pas une statistique de production.',
            'La décision pourrait être de restaurer la description précédente, d’ajouter le cas au jeu de régression et de maintenir le transfert tant que le contrôle n’est pas relancé. Mais la réponse dépendrait des preuves réelles et du coût du service. Le modèle n’est pas tenu responsable du seul pourcentage : qualité du formulaire en entrée, disponibilité de l’intégration et règles métier influencent aussi le résultat. Aucun agent client ou incident réel n’est évoqué ici.'
          ] },
          { title: 'Réviser le contrat de service, pas seulement le modèle', paragraphs: [
            'Quand la fiabilité baisse, cherchez la couche qui a changé : données, consigne, récupération, outil, permission, runtime ou service tiers. Rejouez d’abord un cas contrôlé et vérifiez que les traces permettent d’identifier le premier écart. Un modèle plus récent peut améliorer certaines tâches et en dégrader d’autres ; une architecture ou un prompt qui a été validé auparavant n’est pas certifié indéfiniment. Tenez un historique des versions et reliez les décisions de mise en service aux preuves qui les autorisent.',
            'Les mesures de terrain ne remplacent pas les évaluations avant changement, la revue humaine des cas sensibles ni le mécanisme d’arrêt. Elles complètent ces contrôles en montrant comment le service se comporte dans le temps. Un agent sans actions externes et avec sortie systématiquement relue peut avoir besoin de supervision légère ; un agent qui modifie des dossiers ou déclenche des transactions demande une surveillance et des limites plus strictes. Ajustez la profondeur du dispositif au dommage possible et à la possibilité de revenir sur l’action.'
          ] }
        ], takeaway: 'Mesurez l’état final, les reprises, les transferts et les coûts dans le temps. Reliez chaque alerte à un responsable, une preuve et une réponse testable.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'agent-reliability-in-production', title: 'Evaluate agents in the field: success, recovery, and oversight',
        description: 'Track agent reliability as a service over time, including retries, errors, and human handoffs.', category: 'Operations & R&D',
        introduction: 'A pre-deployment benchmark answers a limited question about a task set; it does not alone show how an agent behaves as inputs, tools, and dependencies change. Field reliability concerns service quality over time: verified outcomes, retries, handoffs, latency, cost, and incidents. Anthropic and OpenAI evaluation resources emphasize traces, final outcomes, and repeatability; OWASP notes that action sequences can reveal deviations that availability alone misses. These are guides from vendors and a security project, not a complete standard. The dashboard proposed here separates product quality, availability, and human oversight.',
        sources: [anthEvals, oaEvals, owaspMonitoring, owaspExcess], sections: [
          { title: 'Define what “success” means', sourceUrls: [anthEvals.url, oaEvals.url], paragraphs: [
            'Describe the unit of work the agent should complete and the state that proves success. A fluent answer is not necessarily a completed action: a booking request requires a booking to exist, a document summary should be tied to consulted sources, and a data change must satisfy invariants. Separate acceptable outcomes, quality criteria, prohibited actions, and cases where the agent should abstain or hand off to a person.',
            'Build several task classes before launch: common, ambiguous, missing data, temporarily unavailable tool, and high-impact action. Offline evals help find regressions, but service behavior also depends on its environment. Official guides describe tasks, traces, graders, and final state as parts of an evaluation harness. Use them as reference points; select criteria with the people responsible for the business outcome.'
          ] },
          { title: 'Measure an end-to-end flow', paragraphs: [
            'At minimum, track tasks received, completed, handed off, and abandoned, plus the share that passes an outcome check. Add end-to-end latency, human recovery time, tool calls, retries, and cost if available. Show the denominator and scope for each metric: “success rate” without defined cases, period, and exclusions is ambiguous. Compare similar tasks instead of mixing simple work with rare but risky cases.',
            'A service can have a good average and a failing subgroup. Inspect input categories, agent and model versions, tools, integrations, and handoff outcomes while avoiding unjustified collection. Label configuration changes and maintenance periods. When case counts are small, report observed counts and uncertainty instead of a highly precise percentage. Do not turn a short fluctuation into a drift claim without checking seasonality, sample size, and upstream changes.'
          ] },
          { title: 'Observe traces and recovery', sourceUrls: [owaspMonitoring.url, anthEvals.url], paragraphs: [
            'For a task sample, link the request, tool decisions, intermediate results, errors, handoffs, and final state. It should be possible to distinguish successful recovery from repeated retries that create side effects. OWASP recommends monitoring called tools, their order, frequency, and parameters to identify atypical sequences. Design that monitoring with identifiers and a retention policy: observability does not require making every conversation accessible to the whole team.',
            'Document conditions that trigger an alert or intervention: more verified errors, denied actions, unavailable tool, call-budget breach, or inconsistent final state. An alert should name an owner and expected response, such as disabling a connector and processing the queue manually. Thresholds are service-specific; they cannot be copied from a vendor article. Test controls too, to avoid non-actionable alerts or silence when behavior is wrong.'
          ] },
          { title: 'Hypothetical example: inspect incomplete requests', paragraphs: [
            'Hypothetical example: an agent classifies synthetic forms and sends uncertain cases to a person. The dashboard separates forms accepted by a consistency check, rejected for missing information, handed off, and tool errors. In a fictional batch of 40 requests, ten have a missing field; a human review confirms which should have been transferred. The team also checks a week of traces for a change after a tool description update. This count is part of a scenario, not a production statistic.',
            'A possible decision might be to restore the earlier description, add the case to a regression set, and keep the handoff until the check is rerun. Actual evidence and service cost would determine the response. The model should not bear responsibility for the percentage alone: input quality, integration availability, and business rules affect outcomes too. No client agent or real incident is described here.'
          ] },
          { title: 'Review the service contract, not only the model', paragraphs: [
            'When reliability falls, look for the changed layer: data, instruction, retrieval, tool, permission, runtime, or third-party service. First replay a controlled case and check whether traces identify the first deviation. A newer model may improve some tasks and degrade others; an architecture or prompt that was validated earlier is not certified indefinitely. Keep a version history and link launch decisions to the evidence that authorizes them.',
            'Field measures do not replace pre-change evaluations, human review of sensitive cases, or a stop mechanism. They complement those controls by showing how the service behaves over time. An agent with no external actions and fully reviewed output may need light supervision; one that modifies records or initiates transactions requires stricter monitoring and limits. Match the depth of the system to potential harm and the ability to reverse an action.'
          ] }
        ], takeaway: 'Measure final state, retries, handoffs, and cost over time. Link every alert to an owner, evidence, and a testable response.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'workflow-analytics-ml', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'analyser-processus-sans-surveiller-personnes', title: 'Analyser les habitudes de travail avec le machine learning sans surveiller les personnes',
        description: 'Utilisez des données minimisées pour comprendre un processus, avec une finalité claire et des garanties adaptées au droit du travail.', category: 'Exploitation & R&D',
        introduction: 'Des traces d’activité peuvent aider à repérer une file d’attente ou une étape qui bloque. Elles peuvent aussi dériver vers le classement de personnes, la prédiction de leur rendement ou une surveillance plus large que l’objectif initial. Ces usages ne sont pas équivalents. La CNIL indique que le contrôle de l’activité au travail doit être justifié et proportionné, porté à la connaissance des personnes et soumis à consultation des instances représentatives selon les situations. Elle distingue également le profilage individualisé de statistiques purement agrégées, sans que l’agrégation dispense automatiquement de toute analyse de protection des données. Cet article propose une méthode de diagnostic de processus ; il ne constitue pas un avis juridique et n’autorise pas à réutiliser des données collectées pour une autre finalité.',
        sources: [cnilControl, cnilProfiling, cnilHR], sections: [
          { title: 'Formuler une question sur le processus', sourceUrls: [cnilControl.url], paragraphs: [
            'Commencez par une question qui décrit une étape, non une personne : « à quel moment les demandes attendent-elles une information ? » ou « quelle catégorie de dossier est renvoyée pour correction ? ». Décrivez la décision opérationnelle envisagée et pourquoi les données existantes ne suffisent pas. Écartez les objectifs vagues comme « mieux mesurer la productivité ». Ils ne déterminent ni le périmètre ni la nécessité des indicateurs et encouragent une collecte toujours plus large.',
            'Délimitez la population, la période, les outils et les événements examinés. Les données d’un outil peuvent révéler une activité professionnelle, mais aussi des habitudes, des absences, des relations ou des comportements personnels. La CNIL rappelle que le pouvoir de contrôle de l’employeur n’est pas sans limite et que les dispositifs doivent, notamment, satisfaire aux exigences de justification et de proportionnalité. Les obligations précises dépendent du contexte, du dispositif et du droit applicable ; la validation par les responsables compétents doit précéder l’analyse.'
          ] },
          { title: 'Séparer diagnostic agrégé et jugement individuel', sourceUrls: [cnilProfiling.url], paragraphs: [
            'Un tableau agrégé par étape, équipe ou type de demande peut suffire à voir qu’un formulaire provoque des retours. Il ne faut pas en déduire qu’un indicateur individuel serait nécessaire. La CNIL décrit le profilage comme l’analyse ou la prédiction d’aspects personnels concernant un individu et le distingue des traitements purement statistiques visant une vue d’ensemble sur un groupe. La frontière dépend réellement de la conception : un rapport dit agrégé peut permettre la réidentification si les groupes sont très petits ou si d’autres jeux de données sont accessibles.',
            'Définissez un seuil minimal d’agrégation adapté au risque, supprimez les identifiants inutiles et empêchez les filtres qui isolent une personne. Ce seuil n’est pas une règle légale universelle. Évitez les tableaux de classement, scores de fiabilité ou prédictions sur les salariés si le besoin porte sur un flux. Si une évaluation individuelle est envisagée, il s’agit d’un projet différent qui demande une analyse juridique, sociale et de protection des données dédiée ; une simple moyenne ne neutralise pas cette distinction.'
          ] },
          { title: 'Vérifier nécessité, proportionnalité et information', sourceUrls: [cnilControl.url, cnilHR.url], paragraphs: [
            'Avant de traiter les données, demandez s’il existe un moyen moins intrusif de répondre à la question : mesure de temps d’attente, échantillon de dossiers anonymisés, atelier avec les équipes, ou journal de changement limité. Identifiez les champs strictement nécessaires, leur durée de conservation, les personnes qui y accéderont et les mesures de sécurité. La CNIL explique qu’un contrôle de l’activité doit être nécessaire à son objectif et qu’une surveillance permanente est en général excessive. La finalité déclarée doit aussi correspondre à l’usage réel ; on ne devrait pas réutiliser secrètement un outil conçu pour optimiser un processus afin de surveiller autre chose.',
            'Le guide de la CNIL sur le contrôle des personnes employées rappelle l’information préalable et, selon le contexte, la consultation des instances représentatives. Ne déduisez pas de l’article une réponse automatique sur l’obligation applicable à toute organisation : effectifs, statut, dispositif et droit en vigueur comptent. Prévoyez une information compréhensible sur la finalité, les données, les accès et la durée ; impliquez le délégué à la protection des données, les ressources humaines et les représentants concernés selon les procédures de l’organisme.'
          ] },
          { title: 'Exemple fictif : localiser les retours de formulaires', paragraphs: [
            'Exemple fictif : un service reçoit des demandes internes et souhaite comprendre pourquoi certaines reviennent pour complément. Il remplace d’abord l’analyse des messages par des catégories de retour choisies à l’avance : pièce absente, champ incohérent, consigne imprécise. Un échantillon sans noms est examiné par des personnes habilitées, puis les résultats sont agrégés par étape et période suffisamment large. L’objectif est de réécrire la consigne ou le formulaire, pas de mesurer la vitesse de chaque personne qui saisit les demandes.',
            'Avant toute analyse, l’équipe vérifie la provenance des données, l’information déjà donnée, la nécessité du nouvel usage, la durée de conservation et les consultations pertinentes. Si les groupes sont trop petits, elle élargit la période ou choisit une méthode qualitative. Les événements détaillés ne sont pas ajoutés à une base de suivi individuelle. Ce scénario est fictif et ne décrit ni un dispositif installé ni une conclusion juridique ; chaque organisation doit examiner ses faits avec ses interlocuteurs compétents.'
          ] },
          { title: 'Garder un contrôle humain sur les conclusions', paragraphs: [
            'Un modèle peut regrouper des descriptions, repérer une séquence inhabituelle ou aider à formuler des hypothèses. Il ne doit pas transformer une corrélation en cause ni attribuer un comportement à une personne sans examen. Les données manquantes, changements d’outil, horaires variables et tâches invisibles peuvent expliquer un motif apparent. Faites valider les catégories par les personnes qui connaissent le processus, consignez les désaccords et vérifiez les conclusions sur des exemples expurgés des identifiants non nécessaires.',
            'Ne déployez pas automatiquement une action sur une personne à partir d’un score exploratoire. Si le but évolue vers la performance individuelle ou une décision à l’égard d’un salarié, arrêtez l’analyse de processus et ouvrez une évaluation distincte des obligations, des droits et des effets. La méthode agrégée n’est pas adaptée à une urgence de sécurité nécessitant une réponse ciblée, mais cette exception ne justifie pas une collecte générale en continu. L’issue utile peut être une amélioration du formulaire, une clarification de responsabilité ou la décision de ne pas instrumenter.'
          ] }
        ], takeaway: 'Posez une question sur une étape, minimisez et agréguez les données, puis vérifiez la finalité, la proportionnalité, l’information et les consultations requises avec les bons interlocuteurs.', service: { href: '/pilotage-projet-complexe/', label: 'Découvrir le pilotage de projets complexes' }
      },
      en: {
        slug: 'analyze-workflows-without-monitoring-people', title: 'Analyze work patterns with machine learning without monitoring people',
        description: 'Use minimized data to understand a process, with a clear purpose and safeguards appropriate to employment law.', category: 'Operations & R&D',
        introduction: 'Activity traces can help locate a queue or a blocked step. They can also drift into ranking people, predicting their performance, or monitoring beyond the original purpose. Those uses are not equivalent. France’s CNIL says workplace activity monitoring must be justified and proportionate, disclosed to the people concerned, and subject to consultation with employee representative bodies where required by the situation. It also distinguishes individualized profiling from purely aggregated statistics, while aggregation does not automatically remove every data-protection question. This article proposes a process-diagnostic method; it is not legal advice and does not authorize reuse of data collected for another purpose.',
        sources: [cnilControl, cnilProfiling, cnilHR], sections: [
          { title: 'Ask a question about the process', sourceUrls: [cnilControl.url], paragraphs: [
            'Start with a question about a step, not a person: “when do requests wait for information?” or “which request category is returned for correction?” Describe the operational decision and why existing data are insufficient. Avoid vague aims such as “measure productivity better.” They define neither scope nor indicator necessity and encourage broader collection over time.',
            'Bound the population, period, tools, and events. Data from a work tool can reveal professional activity as well as habits, absences, relationships, or personal behavior. CNIL notes that an employer’s power to monitor work is limited and that monitoring devices must, among other things, meet justification and proportionality requirements. Exact obligations depend on context, the device, and applicable law; review by the appropriate people should precede analysis.'
          ] },
          { title: 'Separate aggregate diagnosis from individual judgment', sourceUrls: [cnilProfiling.url], paragraphs: [
            'A table aggregated by step, team, or request type may be enough to show that a form causes rework. That does not mean an individual metric is necessary. CNIL describes profiling as analyzing or predicting personal aspects about an individual and distinguishes it from purely statistical processing intended to provide a group-level view. The actual design matters: a supposedly aggregate report can allow re-identification when groups are tiny or other datasets are accessible.',
            'Set a minimum aggregation threshold appropriate to the risk, remove unnecessary identifiers, and prevent filters that isolate one person. This threshold is not a universal legal rule. Avoid rankings, reliability scores, or employee predictions when the need concerns a workflow. If individual assessment is contemplated, it is a separate project requiring dedicated legal, social, and data-protection analysis; a simple average does not erase that distinction.'
          ] },
          { title: 'Check necessity, proportionality, and notice', sourceUrls: [cnilControl.url, cnilHR.url], paragraphs: [
            'Before processing data, ask whether a less intrusive method could answer the question: waiting-time measures, a sample of anonymized cases, a team workshop, or a limited change log. Identify strictly necessary fields, retention period, authorized readers, and security measures. CNIL says workplace monitoring must be necessary for its purpose and continuous surveillance is generally excessive. The stated purpose must also match actual use; a tool designed to improve workflow should not be secretly reused to monitor something else.',
            'CNIL guidance on monitoring employees recalls prior notice and, depending on context, consultation with employee representatives. Do not infer an automatic answer for every organization: workforce size, status, device, and current law matter. Plan clear information about purpose, data, access, and duration; involve the data protection officer, HR, and representatives according to the organization’s procedures.'
          ] },
          { title: 'Hypothetical example: locate form rework', paragraphs: [
            'Hypothetical example: an internal service receives requests and wants to understand why some are returned for more information. Instead of analyzing message content, it first defines return categories: missing attachment, inconsistent field, or unclear instruction. An authorized team reviews a sample without names, then aggregates results by step and a sufficiently broad period. The aim is to rewrite the instruction or form, not to measure the speed of each person entering requests.',
            'Before analysis, the team checks data provenance, prior notice, necessity of the new use, retention period, and relevant consultations. If groups are too small, it broadens the period or chooses a qualitative method. Detailed events are not added to an individual tracking database. This scenario is fictional and describes neither an installed system nor a legal conclusion; each organization must review its facts with the appropriate stakeholders.'
          ] },
          { title: 'Keep human judgment in the conclusions', paragraphs: [
            'A model may group descriptions, flag an unusual sequence, or help formulate hypotheses. It should not turn correlation into cause or attribute behavior to an individual without review. Missing data, tool changes, variable schedules, and invisible tasks may explain an apparent pattern. Have people who know the process validate categories, record disagreements, and check conclusions against examples stripped of unnecessary identifiers.',
            'Do not automatically act on an individual based on an exploratory score. If the goal shifts toward individual performance or a decision about an employee, stop the process analysis and begin a separate assessment of obligations, rights, and effects. The aggregate method is not suited to a safety emergency requiring a targeted response, but that exception does not justify continuous general collection. A useful outcome may be a better form, clearer ownership, or a decision not to instrument at all.'
          ] }
        ], takeaway: 'Ask about a process step, minimize and aggregate data, then review purpose, proportionality, notice, and required consultation with the right stakeholders.', service: { href: '/en/project-leadership/', label: 'Explore complex project leadership' }
      }
    }
  },
  {
    id: 'personal-ai-lab', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'laboratoire-ia-reproductible-budget-limite', title: 'Monter un laboratoire IA reproductible avec des moyens limités',
        description: 'Construisez un banc d’essai isolé avec données synthétiques, versions explicites et carnet d’essais léger.', category: 'Exploitation & R&D',
        introduction: 'Un laboratoire IA utile n’a pas besoin d’être un cluster coûteux. Il lui faut surtout une question limitée, un environnement qui n’expose pas de données ou d’actions sensibles, et assez de notes pour refaire l’essai. Les guides d’évaluation d’OpenAI et d’Anthropic recommandent des tâches définies, des jeux de cas et des exécutions répétables ; la documentation OpenTelemetry aide à penser les traces comme des événements corrélables. Ces ressources ne prescrivent pas l’infrastructure idéale pour une équipe donnée. La proposition ici vise un petit banc d’essai : fichiers synthétiques, paramètres enregistrés, environnement isolé, critère de réussite concret et arrêt explicite si la question peut être résolue sans davantage de calcul.',
        sources: [oaEvals, anthEvals, otelLogs], sections: [
          { title: 'Écrire une question et un oracle modestes', sourceUrls: [oaEvals.url, anthEvals.url], paragraphs: [
            'Commencez par une question que l’essai peut trancher : « la nouvelle consigne extrait-elle les dates requises sans perdre le fuseau ? » ou « le modèle choisit-il le bon outil sur des demandes volontairement ambiguës ? ». Définissez un oracle avant de lancer les variantes : résultat de référence, invariants, cas d’abstention et critères qu’une personne doit examiner. Si le sujet est une tâche subjective, écrivez une courte rubrique avec exemples de niveaux avant de comparer des sorties.',
            'Réduisez le périmètre au plus petit ensemble de cas qui sépare les options. Un laboratoire ne prouve pas la performance en production ; il permet d’examiner une hypothèse dans des conditions contrôlées. Les pages OpenAI et Anthropic proposent de passer des traces exploratoires à des ensembles et essais répétables une fois le comportement attendu mieux défini. Conservez cette distinction dans le carnet afin que le lecteur d’un résultat ne le prenne pas pour une garantie générale.'
          ] },
          { title: 'Isoler outils, données et permissions', paragraphs: [
            'Utilisez des données synthétiques ou des extraits expurgés autorisés, avec une provenance et une raison consignées. Retirez noms, identifiants, secrets, contenus confidentiels et chemins d’accès réels. Préférez des outils simulés qui retournent des réponses déterministes à de vrais comptes ou services. Si l’essai doit atteindre un service externe, créez une zone de test dédiée, des identifiants à privilèges minimaux et une limite de dépense ou de requêtes. L’objectif est que l’erreur reste confinée au laboratoire.',
            'Séparez l’environnement d’essai des espaces de travail quotidiens. Notez les versions de dépendances, variables de configuration non secrètes, modèle ou endpoint choisi, prompt, skill, outils et date. Ne versez pas de jeton d’accès dans le carnet ou les traces. Des permissions réduites rendent les résultats plus faciles à comprendre, car elles limitent les différences cachées entre essais et les conséquences d’un mauvais appel d’outil.'
          ] },
          { title: 'Versionner les cas et les traces utiles', sourceUrls: [otelLogs.url], paragraphs: [
            'Chaque cas doit recevoir un identifiant stable, une entrée synthétique, les préconditions, l’état attendu et une catégorie de difficulté. Pour chaque exécution, gardez les versions, paramètres, date, résultat, erreurs, nombre d’étapes et référence à une trace. OpenTelemetry décrit comment les identifiants de trace et de span relient les événements qui appartiennent à la même exécution. Cela ne signifie pas qu’il faille conserver tout le texte brut : stockez seulement ce dont l’analyse a besoin et appliquez des droits et une durée adaptés.',
            'Évitez de modifier silencieusement un cas en place. Quand une ambiguïté est clarifiée ou un nouveau défaut découvert, créez une version ou ajoutez une note et gardez l’historique. Le jeu d’essai doit inclure des cas ordinaires et des cas de bord, mais il n’a pas besoin de devenir une collection sans fin. Supprimez les doublons, documentez ce qu’un cas couvre et marquez les limites encore inconnues. Une trace sans lien vers sa configuration exacte est difficile à comparer.'
          ] },
          { title: 'Exemple fictif : comparer deux consignes sur des tickets inventés', paragraphs: [
            'Exemple fictif : une équipe veut savoir si une consigne de tri aide à classer des demandes de support. Elle crée douze tickets synthétiques : quatre catégories nettes, quatre demandes manquant une information et quatre qui ne devraient pas être classées automatiquement. Elle note la catégorie attendue, la raison de transfert et les mots qui ne doivent pas être inventés. Les deux variantes reçoivent le même lot dans des sessions fraîches ; un script compare les étiquettes et une personne examine les abstentions.',
            'Le carnet consigne modèle, versions de consigne, réglages accessibles, durée, appels d’outils et désaccords. Si les deux options sont équivalentes sur les cas simples mais divergent sur les demandes manquantes, la prochaine étape n’est pas un lancement : il faut préciser la règle ou enrichir les exemples. Ce scénario est hypothétique ; il n’affirme aucun essai effectué, résultat observé ou gain de performance.'
          ] },
          { title: 'Limiter l’effort et décider quand arrêter', paragraphs: [
            'Fixez un budget de temps, de requêtes et de calcul pour le laboratoire. Choisissez une étape de décision : poursuivre si une incertitude importante reste et que les résultats pourraient changer une décision, arrêter si toutes les variantes échouent au même critère, ou transférer vers une évaluation plus représentative quand les données ou risques diffèrent trop. Un laboratoire sous-dimensionné peut orienter une enquête, mais ne devrait jamais certifier une action à fort impact.',
            'Une fiche de conclusion tient en quelques points : question, méthode, environnement, résultat descriptif, limites et prochaine action. Pour une tâche simple et réversible, une inspection manuelle peut répondre plus vite qu’une plateforme complète. Pour une décision de production, ajoutez l’évaluation de sécurité, les cas de reprise et la supervision opérationnelle. La reproductibilité ne signifie pas que chaque essai donnera la même sortie ; elle signifie qu’on connaît les conditions et qu’on peut examiner les écarts.'
          ] }
        ], takeaway: 'Commencez avec une question, un oracle et un jeu de données synthétiques. Isolez les permissions, consignez les versions et arrêtez dès que l’expérience ne change plus la décision.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'reproducible-ai-lab-on-a-small-budget', title: 'Build a reproducible AI lab with limited resources',
        description: 'Create an isolated test bench with synthetic data, explicit versions, and a lightweight experiment log.', category: 'Operations & R&D',
        introduction: 'A useful AI lab does not need an expensive cluster. It mainly needs a bounded question, an environment that does not expose sensitive data or actions, and enough notes to repeat the trial. OpenAI and Anthropic evaluation guides recommend defined tasks, case sets, and repeatable runs; OpenTelemetry documentation helps frame traces as correlatable events. These resources do not prescribe the ideal infrastructure for every team. The proposal here is a small test bench: synthetic files, recorded settings, an isolated environment, a concrete success criterion, and a clear stop condition when no more compute is needed to answer the question.',
        sources: [oaEvals, anthEvals, otelLogs], sections: [
          { title: 'Write a question and modest oracle', sourceUrls: [oaEvals.url, anthEvals.url], paragraphs: [
            'Start with a question the trial can answer: “does the new instruction extract required dates without losing the time zone?” or “does the model choose the correct tool on deliberately ambiguous requests?” Define an oracle before running variants: reference result, invariants, abstention cases, and criteria a person should review. For subjective work, write a short rubric with examples of levels before comparing outputs.',
            'Reduce scope to the smallest case set that separates options. A lab does not prove production performance; it lets you inspect a hypothesis under controlled conditions. OpenAI and Anthropic pages suggest moving from exploratory traces to repeatable datasets and runs once expected behavior is clearer. Preserve that distinction in the log so a reader does not mistake a result for a general guarantee.'
          ] },
          { title: 'Isolate tools, data, and permissions', paragraphs: [
            'Use synthetic data or authorized redacted excerpts, with provenance and reason recorded. Remove names, identifiers, secrets, confidential content, and real access paths. Prefer simulated tools returning deterministic answers over real accounts or services. If a trial must reach an external service, create a dedicated test area, minimum-privilege credentials, and a spend or request limit. The goal is to contain mistakes within the lab.',
            'Separate the test environment from everyday workspaces. Record dependency versions, non-secret configuration, model or endpoint, prompt, skill, tools, and date. Do not put access tokens in a notebook or traces. Restricted permissions make results easier to interpret because they reduce hidden differences between runs and limit the consequences of a bad tool call.'
          ] },
          { title: 'Version cases and useful traces', sourceUrls: [otelLogs.url], paragraphs: [
            'Give each case a stable identifier, synthetic input, preconditions, expected state, and difficulty category. For each run, retain versions, settings, date, outcome, errors, step count, and a trace reference. OpenTelemetry describes how trace and span IDs link events from the same execution. That does not mean all raw text should be kept: store only what analysis needs, with appropriate access and retention.',
            'Avoid silently changing a case in place. When ambiguity is clarified or a new failure is discovered, create a version or note and retain history. The set should include ordinary and edge cases without becoming an endless collection. Remove duplicates, document coverage, and mark remaining unknowns. A trace without its exact configuration is hard to compare.'
          ] },
          { title: 'Hypothetical example: compare two instructions on fictional tickets', paragraphs: [
            'Hypothetical example: a team wants to know whether a triage instruction helps classify support requests. It creates twelve synthetic tickets: four clear categories, four missing information, and four that should not be automatically classified. It records the expected category, handoff reason, and statements that must not be invented. Both variants receive the same set in fresh sessions; a script compares labels and a person reviews abstentions.',
            'The log records model, instruction versions, available settings, duration, tool calls, and disagreements. If both options perform similarly on simple cases but differ on missing information, the next step is not launch: clarify the rule or improve examples. This scenario is hypothetical; it does not claim an experiment was run, an outcome observed, or a performance gain.'
          ] },
          { title: 'Limit effort and decide when to stop', paragraphs: [
            'Set time, request, and compute budgets for the lab. Choose a decision gate: continue if an important uncertainty remains and results could change a choice; stop if all variants fail the same criterion; or move to a more representative evaluation when data or risks differ too much. An undersized lab can guide investigation but should never certify a high-impact action.',
            'A conclusion card can be short: question, method, environment, descriptive result, limits, and next action. For a simple reversible task, manual inspection may answer faster than a complete platform. For a production decision, add security evaluation, recovery cases, and operational oversight. Reproducibility does not mean every run returns the same output; it means conditions are known and differences can be examined.'
          ] }
        ], takeaway: 'Start with a question, an oracle, and synthetic data. Isolate permissions, record versions, and stop when the experiment no longer changes the decision.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'agent-loop-recovery', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'diagnostiquer-boucle-agent-avant-relance', title: 'Quand un agent boucle ou abandonne : diagnostiquer avant de relancer',
        description: 'Utilisez une procédure de diagnostic pour limiter les retries, préserver l’état et reprendre sans dupliquer les effets.', category: 'Exploitation & R&D',
        introduction: 'Quand un agent s’arrête ou répète une action, le relancer immédiatement peut répéter la cause : outil encore indisponible, état manquant, limite atteinte ou sortie impossible à interpréter. Une reprise sûre commence par établir ce qui s’est réellement passé, puis à décider si l’on peut continuer, recommencer depuis un point connu ou transférer le travail. OWASP avertit qu’une boucle d’appels sans budget peut épuiser des ressources, et ses recommandations de supervision soulignent l’intérêt des traces d’outils. Anthropic décrit, dans ses propres systèmes, checkpoints et reprises après erreurs. Ces sources soutiennent des principes généraux, sans définir le runbook d’une application particulière. Le guide suivant propose des arrêts explicites et une reprise contrôlée.',
        sources: [owaspExcess, owaspMonitoring, anthMulti, anthHarness], sections: [
          { title: 'Reconnaître les symptômes sans les confondre', sourceUrls: [owaspExcess.url, owaspMonitoring.url], paragraphs: [
            'Une boucle visible peut être une répétition du même appel, une alternance entre deux outils, une recherche qui élargit sans résultat ou une suite de réponses qui ne modifie pas l’état. Un abandon peut provenir d’une erreur explicite, d’un délai dépassé, d’un budget atteint ou d’une réponse finale prématurée. Notez le dernier état confirmé et l’étape en cours. L’interface peut afficher un message générique, mais la trace technique doit permettre de distinguer ces situations.',
            'Séparez les causes possibles : panne transitoire du service, paramètres invalides, outil qui retourne une erreur non typée, consigne contradictoire, contexte perdu, permission refusée ou boucle de planification. Ne supposez pas qu’un retry est approprié parce que l’agent n’a pas rendu de réponse. Les guides OWASP sur l’agence excessive et la supervision expliquent respectivement les risques d’autonomie incontrôlée et la valeur de surveiller les appels d’outils et leurs séquences.'
          ] },
          { title: 'Arrêter avec des budgets déterministes', paragraphs: [
            'Fixez un nombre maximal d’étapes, un budget de temps et un plafond d’appels ou de dépenses. Ajoutez une condition d’arrêt quand les mêmes paramètres sont répétés, quand aucun nouvel élément n’apparaît ou quand un outil retourne une erreur permanente. Les valeurs doivent être choisies selon le service et le coût acceptable, pas copiées d’un exemple générique. Une boucle ne devrait pas pouvoir créer elle-même une autorisation infinie en décrivant chaque reprise comme une nouvelle tentative.',
            'Un arrêt est un résultat valable. Affichez ce qui a été confirmé, ce qui reste inconnu et l’action sûre suivante, par exemple demander une précision ou transférer à une personne. Pour une opération irréversible, interrompez avant effet externe si l’état est incertain. Journalisez la raison de l’arrêt avec un code stable et faites une alerte si ce motif augmente. Un mécanisme de budget simple permet de contenir les coûts même lorsque l’agent ne comprend pas qu’il tourne en rond.'
          ] },
          { title: 'Vérifier l’état avant une reprise', sourceUrls: [anthMulti.url, anthHarness.url], paragraphs: [
            'Reconstituez la séquence depuis une trace corrélée : entrée, décision, appel, réponse, écriture éventuelle et accusé de réception. Vérifiez l’état du système cible, car l’absence d’un message de succès ne prouve pas que l’action a échoué. Utilisez un identifiant d’opération ou une clé d’idempotence si le système en offre une. Les retours d’expérience d’Anthropic sur les agents longs décrivent état durable, checkpoints et reprise ; ce sont des choix de harness, pas une solution automatique pour chaque service.',
            'Choisissez l’une de trois voies. Continuer depuis un checkpoint vérifié si les préconditions sont intactes. Recommencer depuis un point sûr après avoir annulé ou confirmé les effets partiels. Transférer si l’état, l’autorisation ou l’intention de l’utilisateur reste ambigu. Évitez de passer au modèle une trace complète contenant des secrets ou des données inutiles ; fournissez plutôt les événements minimaux et les états explicitement confirmés.'
          ] },
          { title: 'Exemple fictif : une recherche recommence après un timeout', paragraphs: [
            'Exemple fictif : un agent lit un dossier puis demande à un outil d’ajouter une étiquette. L’outil dépasse son délai après l’écriture, sans renvoyer l’accusé. Un retry aveugle peut créer une action en double. Le runbook suspend donc les appels, recherche l’identifiant de dossier et l’événement d’écriture, puis vérifie dans le système source si l’étiquette est présente. Si oui, il enregistre la tâche comme terminée ; si non, il fait une tentative bornée ; si l’état est introuvable, il transfère à une personne.',
            'La vérification de l’état, les limites de retry et le contrôle de transfert sont des propositions de conception. Aucun outil, incident client ni traitement réel n’est décrit. Le test de laboratoire pourrait simuler les trois réponses : succès sans accusé, absence d’écriture et état inconnu. Le résultat attendu pour chaque branche est défini avant l’exécution, ce qui permet de vérifier que le système n’improvise pas une réponse dangereuse face à l’incertitude.'
          ] },
          { title: 'Reprendre avec une note de passation exploitable', paragraphs: [
            'Une reprise après interruption ressemble à une passation entre équipes : état confirmé, décisions prises, effets appliqués, hypothèses, budget restant et prochaine étape. Les travaux d’Anthropic sur les harnesses longue durée mettent en avant des artefacts lisibles entre sessions parce qu’un résumé seul peut perdre du contexte. Gardez les notes brèves et vérifiables ; un commentaire « j’ai probablement envoyé la demande » ne doit pas être confondu avec un accusé de l’application.',
            'Après résolution, classez le cas : défaut de l’outil, limite de budget, instruction ambiguë, état non durable ou lacune de supervision. Ajoutez un cas synthétique de régression si la défaillance peut être rejouée. Ne relancez pas un système en production tant que les contrôles d’impact n’ont pas été validés. Pour une tâche exploratoire et sans effet externe, une reprise simple peut suffire ; pour écriture, paiement, publication ou accès à des données, la confirmation d’état et l’autorisation doivent être beaucoup plus strictes.'
          ] }
        ], takeaway: 'Arrêtez les boucles par un budget déterministe, inspectez l’état externe, puis continuez depuis un checkpoint, reprenez proprement ou transférez selon ce qui est vérifiable.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'diagnose-agent-loops-before-retrying', title: 'When an agent loops or stops: diagnose before retrying',
        description: 'Use a diagnostic procedure to limit retries, preserve state, and resume without duplicating side effects.', category: 'Operations & R&D',
        introduction: 'When an agent stops or repeats an action, immediately retrying may repeat the cause: an unavailable tool, missing state, exhausted limit, or uninterpretable output. Safe recovery starts by establishing what actually happened, then deciding whether to continue, restart from a known point, or hand off the work. OWASP warns that loops without budgets can exhaust resources, and its monitoring guidance highlights tool traces. Anthropic describes checkpoints and recovery after errors in its own systems. These sources support general principles but do not define a runbook for a particular application. This guide proposes explicit stops and controlled recovery.',
        sources: [owaspExcess, owaspMonitoring, anthMulti, anthHarness], sections: [
          { title: 'Recognize symptoms without conflating them', sourceUrls: [owaspExcess.url, owaspMonitoring.url], paragraphs: [
            'A visible loop may repeat the same call, alternate between two tools, broaden a search without results, or produce responses that do not change state. An apparent stop may come from an explicit error, timeout, exhausted budget, or premature final response. Record the last confirmed state and current step. The UI may show a generic message, but the technical trace should distinguish these situations.',
            'Separate possible causes: transient service outage, invalid parameters, tool returning an untyped error, contradictory instruction, lost context, denied permission, or planning loop. Do not assume retry is appropriate because the agent has not returned an answer. OWASP guidance on excessive agency and monitoring respectively explains risks of uncontrolled autonomy and the value of watching tool calls and sequences.'
          ] },
          { title: 'Stop with deterministic budgets', paragraphs: [
            'Set a maximum number of steps, time budget, and call or spend cap. Add a stop condition when the same parameters repeat, no new evidence appears, or a tool returns a permanent error. Choose values for the service and acceptable cost; do not copy a generic example. A loop should not be able to create infinite authorization by describing each retry as a new attempt.',
            'Stopping is a valid outcome. Show what is confirmed, what remains unknown, and the next safe action, such as requesting clarification or handing off to a person. For an irreversible operation, pause before the external effect when state is uncertain. Log the stop reason with a stable code and alert if it increases. A simple budget mechanism contains cost even when the agent does not understand that it is stuck.'
          ] },
          { title: 'Check state before resuming', sourceUrls: [anthMulti.url, anthHarness.url], paragraphs: [
            'Reconstruct the sequence from a correlated trace: input, decision, call, response, possible write, and acknowledgement. Check target-system state because a missing success message does not prove the action failed. Use an operation ID or idempotency key if the system supports one. Anthropic’s long-running agent reports describe durable state, checkpoints, and resumption; those are harness choices, not an automatic solution for every service.',
            'Choose one of three paths. Continue from a verified checkpoint if preconditions still hold. Restart from a safe point after confirming or undoing partial effects. Hand off if state, authorization, or user intent remains ambiguous. Avoid passing a full trace containing secrets or irrelevant data to the model; provide only minimal events and explicitly confirmed state.'
          ] },
          { title: 'Hypothetical example: a search retries after a timeout', paragraphs: [
            'Hypothetical example: an agent reads a case and asks a tool to add a label. The tool times out after writing, without returning an acknowledgement. A blind retry may duplicate the action. The runbook therefore pauses calls, looks up the case identifier and write event, then checks the source system for the label. If present, it records completion; if absent, it makes one bounded attempt; if state cannot be determined, it hands off to a person.',
            'State verification, retry limits, and handoff control are design proposals. No real tool, client incident, or live operation is described. A lab test could simulate all three outcomes: success without acknowledgement, no write, and unknown state. The expected result for each branch is defined before execution, making it possible to check that the system does not improvise a dangerous response under uncertainty.'
          ] },
          { title: 'Resume with a useful handoff note', paragraphs: [
            'Recovery after interruption resembles a shift handoff: confirmed state, decisions, applied effects, assumptions, remaining budget, and next step. Anthropic work on long-running harnesses highlights readable artifacts between sessions because a summary alone may lose context. Keep notes brief and verifiable; “I probably sent the request” must not be mistaken for an application acknowledgement.',
            'After resolution, classify the case: tool defect, budget limit, ambiguous instruction, non-durable state, or oversight gap. Add a synthetic regression case if the failure can be replayed. Do not restart a production system until impact controls are validated. For exploratory work with no external effect, simple resumption may be enough; for writes, payments, publication, or data access, state confirmation and authorization should be much stricter.'
          ] }
        ], takeaway: 'Stop loops with deterministic budgets, inspect external state, then continue from a checkpoint, restart safely, or hand off based on what can be verified.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
  {
    id: 'agent-instruction-portability', preparedAt: '2026-10-29', status: 'review', copy: {
      fr: {
        slug: 'portabilite-instructions-agents-ia', title: 'Codex, Claude et Copilot : ce qui se transporte et ce qui doit être retesté',
        description: 'Distinguez les instructions réutilisables des outils, permissions et comportements qui appartiennent à chaque runtime.', category: 'Exploitation & R&D',
        introduction: 'Des fichiers Markdown et un format partagé de skills donnent une première impression de portabilité : on peut déplacer du texte, un dossier et des exemples entre plusieurs assistants. Pourtant, un fichier reconnu par différents environnements ne rend pas leurs outils, permissions, règles de découverte, contextes ou comportements équivalents. La documentation d’OpenAI décrit les skills comme des dossiers de consignes et ressources et indique une compatibilité avec le standard Agent Skills dans le cadre de son API. Les recommandations Codex et Claude Code décrivent aussi des mécanismes propres à leurs produits. Cet article propose un inventaire de ce qui se transporte et un protocole d’adaptation, sans prétendre que les produits cités ont des interfaces identiques.',
        sources: [oaSkills, skillSpec, codexGuide, claudeBest, oaPromptSkills], sections: [
          { title: 'Séparer contenu commun et interprétation hôte', sourceUrls: [oaSkills.url, skillSpec.url], paragraphs: [
            'Les instructions métier peuvent souvent être conservées : objectif, informations requises, séquence de décision, exemples d’entrée et de sortie, critères de qualité et conditions d’abstention. Un format de fichiers commun aide à transporter cette procédure et ses ressources. La spécification Agent Skills décrit le manifeste et la structure du paquet ; OpenAI présente ses skills comme des instructions réutilisables avec fichiers d’appui et mentionne leur compatibilité avec le standard. Cette compatibilité formelle ne garantit ni la même activation ni la même qualité d’exécution.',
            'Les mécanismes du moteur sont une autre couche : quel fichier est découvert automatiquement, quand son contenu est chargé, comment priorité et conflit sont gérés, quelle commande est disponible, quelle interface appelle un outil, et comment les autorisations sont imposées. Une consigne demandant « lance le vérificateur » ne crée pas la commande, ne lui donne pas accès au système et ne prouve pas qu’elle s’exécute dans un environnement donné. Étiquetez chaque instruction comme règle métier, convention de format ou exigence propre à un runtime.'
          ] },
          { title: 'Établir un inventaire avant migration', paragraphs: [
            'Pour chaque élément, notez sa fonction, son emplacement, le responsable, son mode de chargement, ses dépendances, ses outils et ses effets. Listez également les variables d’environnement, scripts, formats de données, hypothèses de chemin, mécanismes d’approbation, hooks et actions refusées. Séparez instructions obligatoires, préférences de style, exemples et étapes manuelles. Les documentations officielles sont la source de référence pour le comportement annoncé ; un fichier portant le même nom dans deux produits n’est pas une preuve d’équivalence.',
            'Construisez une carte à trois colonnes : réutilisable sans changement, à adapter, et à reconstruire ou laisser de côté. Par exemple, un glossaire métier peut passer tel quel ; une règle de détection doit être réécrite si l’activation diffère ; un hook propriétaire ou un outil n’a pas nécessairement d’équivalent ailleurs. Gardez une version par plateforme plutôt que des conditions ambiguës dans un seul document, si ces branches rendent les consignes difficiles à maintenir.'
          ] },
          { title: 'Comparer les comportements avec un contrat de tâches', sourceUrls: [codexGuide.url, claudeBest.url, oaSkills.url], paragraphs: [
            'Choisissez des tâches qui testent les attentes plutôt que le nom du fichier : tâche directe, tâche qui ne doit pas activer le skill, tâche avec information manquante, et cas où l’agent doit demander confirmation. Fournissez les mêmes entrées synthétiques et les mêmes résultats attendus, puis exécutez-les dans des sessions neuves avec les configurations documentées. Comparez activation, étapes, résultat, appel d’outil, permission et comportement d’échec. Notez les différences de produit et de version : le contexte et les réglages peuvent influencer le résultat autant que le texte porté.',
            'Un transfert est prêt seulement lorsque les critères essentiels passent sur la cible et que les différences restantes sont explicites. Pour une consigne non critique, une vérification manuelle de quelques cas peut suffire. Pour une action qui modifie un dépôt ou touche des données externes, testez autorisation, refus, reprise et traces avant de la mettre à disposition. Les pages officielles OpenAI, Claude Code et Codex décrivent leurs environnements respectifs ; elles ne prouvent pas les capacités de GitHub Copilot. Consultez aussi la documentation Microsoft correspondant précisément à l’édition Copilot utilisée.'
          ] },
          { title: 'Exemple fictif : transporter une procédure de revue', paragraphs: [
            'Exemple fictif : une équipe a un skill qui demande à un assistant de résumer un changement, vérifier deux conventions de dépôt et signaler les points à faire relire. Le contenu portable comprend les conventions, les exemples et la forme du rapport. Une liste séparée indique les commandes de test disponibles, les chemins à ignorer et les contrôles d’accès propres au dépôt. Dans le second runtime, l’équipe adapte le mécanisme de découverte, remplace les commandes incompatibles et réduit les permissions au besoin de lecture.',
            'Elle teste ensuite un changement correct, une violation de convention et un cas où la commande n’existe pas. Le résultat attendu inclut une abstention claire lorsque le vérificateur manque, et non une affirmation de test réussi. Si la procédure ne détecte pas la violation, l’équipe corrige l’adaptation et rejoue le cas. Ce scénario est hypothétique ; il ne décrit aucune migration réellement effectuée ni n’attribue une capacité précise à un produit particulier.'
          ] },
          { title: 'Préserver les contrôles et accepter les écarts', paragraphs: [
            'La portabilité ne doit jamais être traitée comme une migration implicite de sécurité. Vérifiez séparément les permissions réelles, les accès réseau, les secrets, les confirmations et les limites d’écriture dans le nouveau runtime. OWASP souligne ailleurs que les fonctionnalités, privilèges et autonomie excessifs sont des causes de risque ; réutiliser une phrase de prudence ne remplace pas un contrôle technique. Gardez les configurations minimales et les règles d’accès à côté de la procédure, avec leur responsable.',
            'Documentez ce qui ne peut pas être transporté et pourquoi : intégration absente, différence de format, manque d’événement observable ou limitation de contrôle. Un portage réussi peut être partiel, ou rester plus coûteux que conserver une version dédiée. Pour des consignes de fond, un format partagé facilite la maintenance ; pour les outils et les mécanismes, la validation est propre au produit. La conclusion utile n’est pas « compatible partout », mais une matrice de tests datée avec les versions couvertes et les écarts encore ouverts.'
          ] }
        ], takeaway: 'Transportez le savoir métier, puis adaptez et retestez les mécanismes du runtime. Un format commun ne garantit ni activation, permissions ni comportement identique.', service: { href: '/orchestration-agents-ia/', label: 'Découvrir l’orchestration d’agents IA' }
      },
      en: {
        slug: 'portability-of-agent-instructions', title: 'Codex, Claude, and Copilot: what travels and what must be retested',
        description: 'Separate reusable instructions from tools, permissions, and behavior owned by each runtime.', category: 'Operations & R&D',
        introduction: 'Markdown files and a shared skills format make portability look straightforward: text, folders, and examples can be moved between assistants. Yet a file recognized by several environments does not make their tools, permissions, discovery rules, context, or behavior equivalent. OpenAI documentation describes skills as folders of instructions and resources and states compatibility with the Agent Skills standard in the context of its API. Codex and Claude Code guidance also describes product-specific mechanisms. This article offers an inventory of what can move and an adaptation protocol, without claiming that the named products have identical interfaces.',
        sources: [oaSkills, skillSpec, codexGuide, claudeBest, oaPromptSkills], sections: [
          { title: 'Separate shared content from host interpretation', sourceUrls: [oaSkills.url, skillSpec.url], paragraphs: [
            'Business instructions can often be preserved: purpose, required information, decision sequence, input and output examples, quality criteria, and abstention conditions. A shared file format helps carry the procedure and its resources. The Agent Skills specification describes the manifest and package structure; OpenAI presents skills as reusable instructions with supporting files and mentions compatibility with the standard. Formal compatibility guarantees neither identical activation nor execution quality.',
            'Runtime mechanisms are a different layer: which file is discovered automatically, when its contents load, how priority and conflict are handled, what commands exist, how tools are called, and how permissions are enforced. An instruction saying “run the checker” does not create that command, grant system access, or prove it runs in a given environment. Label each instruction as business rule, format convention, or runtime-specific requirement.'
          ] },
          { title: 'Inventory before migration', paragraphs: [
            'For each item, record purpose, location, owner, loading behavior, dependencies, tools, and effects. Also list environment variables, scripts, data formats, path assumptions, approval mechanisms, hooks, and refused actions. Separate mandatory instructions, style preferences, examples, and manual steps. Official documentation is the reference for announced behavior; a file with the same name in two products does not prove equivalence.',
            'Create a three-column map: reusable unchanged, needs adaptation, and must be rebuilt or omitted. A business glossary may move as-is; a detection rule may need rewriting if activation differs; a proprietary hook or tool may have no equivalent elsewhere. Keep one version per platform rather than ambiguous conditional instructions in a single document when those branches make maintenance difficult.'
          ] },
          { title: 'Compare behavior with a task contract', sourceUrls: [codexGuide.url, claudeBest.url, oaSkills.url], paragraphs: [
            'Choose tasks that test expectations rather than filenames: a direct task, one that should not invoke the skill, a task with missing information, and a case requiring confirmation. Provide identical synthetic inputs and expected outcomes, then run them in fresh sessions with documented configurations. Compare activation, steps, result, tool call, permission, and failure behavior. Record product and version differences; context and settings can influence results as much as the carried text.',
            'A transfer is ready only when essential criteria pass on the target and remaining differences are explicit. For a noncritical instruction, a manual review of a few cases may be enough. For an action that changes a repository or external data, test authorization, denial, recovery, and traces before release. OpenAI, Claude Code, and Codex official pages describe their own environments; they do not establish GitHub Copilot capabilities. Consult the Microsoft documentation for the exact Copilot edition in use.'
          ] },
          { title: 'Hypothetical example: transfer a review procedure', paragraphs: [
            'Hypothetical example: a team has a skill asking an assistant to summarize a change, check two repository conventions, and flag items for human review. Portable content includes the conventions, examples, and report shape. A separate list specifies available test commands, paths to ignore, and repository-specific access controls. In the second runtime, the team adapts discovery, replaces incompatible commands, and narrows permissions to read-only needs.',
            'It then tests a compliant change, a convention violation, and a case where the command is missing. The expected result includes a clear abstention when the checker is unavailable, not a claim that a test passed. If the procedure misses the violation, the team fixes the adaptation and reruns the case. This scenario is hypothetical; it describes no completed migration and does not attribute a specific capability to any product.'
          ] },
          { title: 'Preserve controls and accept differences', paragraphs: [
            'Portability must never be treated as an implicit security migration. Separately verify actual permissions, network access, secrets, confirmations, and write limits in the new runtime. OWASP highlights excessive functionality, privilege, and autonomy as risk causes; reusing a cautious sentence does not replace a technical control. Keep minimal configurations and access rules with a named owner alongside the procedure.',
            'Document what cannot move and why: missing integration, format difference, absent observable event, or control limitation. A successful port may be partial or more expensive than maintaining a dedicated version. Shared formats help maintain core instructions; tools and mechanisms need product-specific validation. The useful conclusion is not “works everywhere,” but a dated test matrix with covered versions and open gaps.'
          ] }
        ], takeaway: 'Carry business knowledge, then adapt and retest runtime mechanisms. A shared format does not guarantee identical activation, permissions, or behavior.', service: { href: '/en/agent-orchestration/', label: 'Explore AI agent orchestration' }
      }
    }
  },
];
